pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to keep bins tightly packed.
    // We add the square of the post_residual to discourage "slack" creation.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead matching: If the next item fits into the post_residual, 
    // significantly reward this bin to encourage perfect pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 15.0;
        // Further reward if the resulting space after the next item is minimal.
        let secondary_residual = post_residual - next_item_size;
        score -= (100.0 - secondary_residual as f64) * 0.5;
    }

    // 3. Pressure management: If this is the only bin that fits the item (fitting_bins_count == 1),
    // reduce the penalty to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 4. New bin penalty: If this is a new bin (bin_residual == bin_capacity),
    // apply a heavy penalty unless it's truly required.
    if bin_residual == bin_capacity {
        score += 80.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Global optimization: Favor bins that align with the current mean residual 
    // to keep the bin distribution uniform.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 6. Progress weighting: As the stream nears completion, become more aggressive 
    // about closing bins by penalizing the creation of new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting. We penalize values that are 
    // just below the typical item size (around 40-50).
    let dead_space_penalty = if post_res > 0.0 && post_res < 45.0 {
        (45.0 - post_res).powi(2) * 0.1
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we increase the score (penalty).
    let lookahead_penalty = if next_item_size > 0 && post_res < next_item_size as f64 {
        (next_item_size as f64 - post_res) * 1.5
    } else {
        0.0
    };

    // Stream progression adjustment: As we reach the end of the stream, 
    // we become more aggressive about packing tightly to avoid opening new bins.
    let packing_urgency = (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // If this is a new bin (bin_residual == bin_capacity), we set a high baseline cost.
    // We only open a new bin if the cost of placing in existing bins is higher 
    // than this threshold.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base_cost = 45.0 + (progress * 20.0);

    if is_new_bin {
        score = new_bin_base_cost;
    } else {
        score += dead_space_penalty + lookahead_penalty + packing_urgency;
    }

    // Favor bins that align with the current mean residual to keep distribution uniform.
    let variance_penalty = (post_res - mean_residual).abs() * 0.2;

    score + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize small residuals (fragmentation) that are too small to fit common items.
    let fragmentation_penalty = if post_res > 0.0 && post_res < 15.0 {
        15.0 - post_res
    } else {
        0.0
    };

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    let lookahead_benefit = if next_item_size > 0 && (post_res >= next_item_size as f64) {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin management: discourage opening new bins unless the fit is excellent.
    // As the stream progresses, we become more conservative (higher penalty for new bins).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        30.0 + (progress * 40.0) - (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling: Use mean_residual to balance load across bins.
    // If this bin is emptier than average, it is a good candidate for larger items.
    let load_balance = (bin_residual as f64 - mean_residual).abs() * 0.1;

    let mut score = post_res + (fragmentation_penalty * 2.0) + lookahead_benefit + new_bin_penalty + load_balance;

    // Final adjustment: strongly favor bins that are the only fit for an item to prevent waste.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below the expected mean of typical items (roughly 30-40).
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powi(2) * 1.5;
    }

    // Lookahead logic: if the next item is large, we want to prioritize bins with enough space.
    // If the next item doesn't fit in the current post_residual, we penalize the placement.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic thresholding: as the stream progresses, we become more conservative about opening new bins.
    // We increase the penalty for opening a new bin (bin_residual == bin_capacity) as progress increases.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 30.0);
    }

    // Reward bins that have residuals close to the current mean_residual, 
    // effectively "clustering" similar utilization levels across bins.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 0.2;

    // Favor bins that are "last chances" (fitting_bins_count == 1) to avoid opening new ones,
    // unless the fit is extremely poor.
    if fitting_bins_count == 1 && post > 10.0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for any future item (if known)
    // If next_item_size is 0, we assume a standard distribution floor of 10
    let effective_next = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < effective_next {
        score += (effective_next - post_residual) as f64 * 2.5;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize packing density
    // over opening new bins to minimize fragmentation.
    if is_new_bin {
        // High penalty for opening new bins if there are existing fitting options,
        // scaled by progress to force tighter packing near the end.
        score += (fitting_bins_count as f64 * 15.0) * (1.0 + progress);

        // Penalize opening a new bin if the current mean residual is already high
        score += mean_residual * 0.5;
    } else {
        // For existing bins, reward using bins that are already 'fuller' than average
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Lookahead refinement: If the next item can fit in the current post_residual,
    // strongly incentivize this bin selection.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state stabilizer: Penalize excessive bin counts
    score += (open_bins_count as f64).powf(1.2);

    score
}

