pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A bin is a new bin if bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit strategy).
    // Lower post_residual means tighter packing.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely inefficient (e.g., post_residual > 40).
    if is_new_bin {
        score = 45.0; // Threshold to prevent opening new bins unless all existing fits are poor
    } else {
        // Harmonic logic: Favor fills that leave residuals which are multiples of common item sizes (e.g., 20, 25, 33).
        // Penalize residuals that create "dead space" (small values that are hard to fill).
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }

        // Lookahead heuristic: If next_item_size is large, avoid bins that leave just enough space for it but not much else.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect alignment bonus
                if (post_residual - next_item_size) < 5 {
                    score -= 15.0;
                }
            } else {
                // If next item cannot fit, penalize bins that have a residual slightly less than next_item_size
                if (next_item_size - post_residual) < 10 {
                    score += 10.0;
                }
            }
        }

        // Penalty for using too many bins early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

        // Penalty for bins that deviate significantly from the mean residual (load balancing)
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Only open a new bin if the current fit quality is poor or 
        // if we are nearing the end of the stream and need to clear space.
        score = 25.0 + (progress * 20.0);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prioritize Best-Fit: minimize post_residual.
        // Penalty for leaving "dead space" that cannot accommodate the next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }

        // Penalty for creating bins with very small residuals (fragmentation).
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }

        // Reward filling bins that are already relatively empty to consolidate space.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }

        // Late-stage consolidation: if few items remain, prioritize tight packing.
        if progress > 0.8 {
            score += (post_residual as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We want to minimize the gap to keep bins tight.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward placements that leave "useful" residuals.
    // If post_residual is a multiple of common small item sizes, it's more likely to be filled later.
    let harmonic_penalty = if post_residual > 0 {
        (post_residual % 20) as f64 * 0.5 + (post_residual % 10) as f64 * 0.8
    } else {
        -50.0 // Reward perfect fits (zero residual)
    };
    score += harmonic_penalty;

    // 3. Lookahead Sensitivity: If the next item is large, avoid small post_residuals
    // that would force a new bin for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, prioritize closing them (lower residual)
    // If fitting_bins_count is 1, this is a "forced" choice; we reduce the penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0; 
    }

    // 5. New Bin Thresholding:
    // If current bin is empty (new bin candidate), only pick it if the mean residual
    // of existing bins is already very high (indicating they are all poorly packed).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average space in existing bins is tight
            // or if the current item is very large.
            score = 40.0 + (mean_residual * 0.5) - (item_size as f64 * 0.2);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best-Fit approach).
    // Minimize residual to maximize packing density.
    let mut score = post_res;

    // Penalty for creating a "sliver" (fragmentation) that is too small for common items.
    // We penalize post_residuals in the range [1, 9] heavily, especially as the stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0 * (1.0 + progress);
    }

    // Lookahead coupling: If a second item is coming, favor bins that leave enough space
    // to accommodate the next item (synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly or near-perfectly fit the next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize bins that block the next item from fitting.
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state awareness:
    // If we have many open bins, prioritize closing them by favoring the tightest fit.
    // If we are late in the stream, be more aggressive about using existing bins (penalize new bin opening).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Significantly penalize opening new bins as the stream progresses.
        score += 40.0 * (0.5 + progress);

        // If we have very few open bins, penalize opening another one slightly less.
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // Favor bins that align with the current mean residual to keep bin states uniform.
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Critical constraint: If this is the only bin that fits, prioritize it above opening new ones.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward the placement.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements where the remaining space is slightly larger than the next item
        // to minimize fragmentation, but penalize if it's too small to fit next item.
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            score += 20.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless 
    // the mean_residual is very low (meaning existing bins are already near full).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // 4. Fitting Pressure:
        // If this is the only bin that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 5. Global Balance:
        // Penalize opening too many bins early in the stream.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space left in the bin. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

