        // Penalty for being far from the mean, encourages bin uniformity
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Dynamic threshold: As we near the end of the stream, prioritize closing bins
    if progress > 0.9 {
