    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize extreme fragmentation (dead space < 10) unless it's the very end of the stream
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post) * (1.0 - progress).exp() * 5.0
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the expected future item size
    // We use next_item_size to align, but dampen the effect as the stream nears completion
    let lookahead_alignment = if next_item_size > 0 {
        let diff = (post as f64 - next_item_size as f64).abs();
        (diff / bin_capacity as f64) * 10.0 * progress
    } else {
        0.0
    };

    // Discourage opening new bins early, but allow it if the current fit is poor (high post_residual)
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            40.0 + (open_bins_count as f64 * 2.0)
        } else {
