    };

    // Favor bins that maintain a high density relative to the mean residual
    // This helps keep bins "tight" compared to the average state of the system
    let density_balance = (post - mean_residual).powi(2) * 0.1;

    // Final score: minimize post_residual (Best Fit) with non-linear penalties
    post + fragmentation_penalty + lookahead_alignment + new_bin_penalty + density_balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
