            score -= 30.0;
        } else {
            // Penalize if the current placement prevents the next item from fitting
            score += 15.0;
        }
    }

    // 3. Pressure management: If we are near the end of the sequence, be more conservative
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual > 20 {
        score += 10.0;
    }

    // 4. Fitting constraints: If this is the last chance for the current item, 
    // prioritize fitting it over creating a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly from the mean
    // This promotes filling bins somewhat uniformly
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. New bin bias: Only open a new bin if the fit is truly terrible
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 60.0;
        // Reduce the penalty if the open bins are already very full (mean_residual is low)
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller post_residual (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' that is too small for any future item (if known)
    // If next_item_size is 0, we assume a standard distribution floor of 10
    let effective_next = if next_item_size > 0 { next_item_size } else { 10 };
    if post_residual > 0 && post_residual < effective_next {
        score += (effective_next - post_residual) as f64 * 2.5;
    }

    // Dynamic threshold: As we approach the end of the stream, prioritize packing density
    // over opening new bins to minimize fragmentation.
    if is_new_bin {
        // High penalty for opening new bins if there are existing fitting options,
        // scaled by progress to force tighter packing near the end.
        score += (fitting_bins_count as f64 * 15.0) * (1.0 + progress);

        // Penalize opening a new bin if the current mean residual is already high
        score += mean_residual * 0.5;
    } else {
        // For existing bins, reward using bins that are already 'fuller' than average
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Lookahead refinement: If the next item can fit in the current post_residual,
    // strongly incentivize this bin selection.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state stabilizer: Penalize excessive bin counts
    score += (open_bins_count as f64).powf(1.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a 'fragmented' bin (small residual that likely won't fit future items).
    // We penalize based on a non-linear threshold relative to the capacity.
    if post > 0.0 && post < 25.0 {
        score += (25.0 - post).powf(1.5);
    }

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Dynamic adaptation: As we approach the end of the stream, prioritize packing 
    // tightly (minimizing residual) even if it leads to higher fragmentation, 
    // to avoid leaving many bins partially empty.
    let tightness_factor = 1.0 - progress;
    score += (post * tightness_factor * 0.2);

    // If this is a new bin (bin_residual == bin_capacity), penalize it non-linearly 
    // based on how many existing bins could have fit the current item.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other options exist.
        // Penalty scales with the number of open bins to encourage consolidation.
        score += 40.0 + (fitting_bins_count as f64 * 15.0) + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that keep the mean residual balanced to maintain flexibility.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimize post_residual)
    // We prioritize bins that create the smallest remaining space.

    // 2. Harmonic/Modulo Penalty: Penalize "Fragmenting" residuals.
    // If post_residual is small but not zero, it's often wasted.
    // We reward residuals that are multiples of common item sizes (e.g., 20, 25).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // Strong penalty for "sliver" waste
    } else if post_residual % 20 == 0 {
        score -= 5.0; // Reward harmonic alignment
    }

    // 3. Lookahead Logic: If the next item is large, avoid bins that leave just enough
    // space to be useless for the next item but too small for other potential items.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // This bin becomes a "dead-end" for the next item
            score += 8.0;
        } else if post_residual >= next_item_size {
            // This bin is "future-proofed" for the next item
            score -= 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // force it to have a lower score to prevent opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // 5. Global Density: If we have many open bins, penalize opening new ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Penalize opening a new bin if we are near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is in the "unusable" range (1-9),
    // heavily penalize it to force the packing of larger items or tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Open Bin Pressure: If we are using many bins, penalize opening new ones.
    // If bin_residual == bin_capacity (new bin), apply a penalty proportional to current usage.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Integration: If the next item is large, favor leaving space for it.
    // If the current post_residual is slightly smaller than the next item, it's a "bad" fit.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            score += 20.0;
        } else if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item.
            score -= 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the current item, 
    // reduce its score to prioritize closing it or filling it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Mean Residual Balancing: Prefer bins that stay close to the average residual
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            score -= 50.0;
        }
    }

    // Lookahead logic: if we can fit the next item perfectly (or near perfectly) in the current bin, prioritize it
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        if post_residual >= next_item_size {
            // Reward bins that leave space for the next item
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize bins that make it impossible to fit the next item
            score += 40.0;
        }
    }

    // Balance utilization: prefer bins that stay close to the current mean residual
    // This reduces the variance of open bins, preventing "fragmentation"
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // Favor bins that are already nearly full (Best Fit principle)
    // We heavily penalize large post_residuals (wasted space)
    score += (post_residual as f64).powf(1.2);

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // prioritize this bin to avoid opening a new one later
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-placement residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for leaving a very small, unusable gap (fragmentation avoidance)
    // Residuals between 1 and 9 are extremely difficult to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if next item is large, prioritize bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that leave space for the next item
        } else {
            score += 10.0; // Penalize bins that 'trap' the next item
        }
    }

    // Global state awareness: if we are near the end of the stream, be more aggressive
    // about filling existing bins to avoid opening new ones
    if progress > 0.85 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Heuristic for new bin creation:
    // Only open a new bin if the current fit is poor (large residual)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing ones can fit the item,
            // unless the current open bins are very full (low mean_residual)
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Forced to open a new bin
        }
    }

    // Penalize bins that deviate significantly from the current mean usage
    let current_usage = bin_capacity - post_residual;
    let deviation = (current_usage as f64 - (bin_capacity as f64 - mean_residual)).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the "New Bin" choice heavily unless the fit is truly catastrophic elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        // As the stream progresses, opening new bins becomes increasingly expensive
        (100.0 - (progress * 50.0)) + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: minimize post_residual, but prioritize tight fits (small post_residual)
    // We add a non-linear penalty for larger post_residuals to push towards Best-Fit.
    let fit_score = post * post / 100.0;

    // Lookahead coupling: if the next item is large, favor bins that leave enough room for it.
    // If the current post_residual is smaller than the next item, we penalize it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Penalize fragmented bins: if the residual is too small to fit typical items, 
    // it becomes "dead space". We use the mean_residual to gauge global fragmentation.
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        15.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Combine factors
    // We want to minimize the score, so we add penalties to the base post_residual score.
    new_bin_penalty + fit_score + lookahead_penalty + fragmentation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are too small to fit common item sizes (10-30 range)
    // but large enough to waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Reward creating a perfect fit (zero residual)
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Fragmentation Control: If this is the last chance for the current item (fitting_bins_count == 1),
    // and the residual is very tight, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual < 15 {
        score -= 10.0;
    }

    // 4. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity),
    // penalize it based on how many bins are already open to encourage consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If we have many bins, opening a new one is very costly.
    }

    // 5. Mean Residual Balancing: If this bin is significantly emptier than the mean, 
    // it is a good candidate to fill up.
    if bin_residual > (mean_residual as u32) {
        score -= 5.0;
    }

    // 6. Harmonic Class Logic: Reward residuals that are multiples of 20 (common divisor of 100).
    if post_residual % 20 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit common items (below 10) or create "orphaned" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If next_item_size exists, penalize bins that 
    // cannot accommodate the next item after this one is placed.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the fit is extremely tight (Best-Fit logic).
    if bin_residual == bin_capacity {
        // Only prioritize a new bin if we have too many open bins already or if 
        // existing bins are highly fragmented.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Mean Residual Balancing: Penalize bins that deviate significantly from 
    // the global mean residual to encourage uniform packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency Calibration: If this is the only fitting bin, reduce the penalty 
    // to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Factor: As the stream nears completion, prioritize closing 
    // bins (lower post_residual) to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
