    }

    // Global state optimization: balance the residual across open bins.
    // If current bin residual is much higher than mean, we want to fill it more aggressively.
    let residual_diff = bin_residual as f64 - mean_residual;
    score -= residual_diff * 0.5;

    // New Bin Thresholding:
    // Only open a new bin if the current fit is extremely poor (post_residual is very large)
    // or if we are nearing the end of the stream and need to clear out open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
