        // Penalize opening a new bin heavily unless there are no other good options.
        // If we have many open bins, opening a new one is inefficient.
        score += 50.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward fits that leave a residual close to the expected next item size
        // or close to the global mean, reducing fragmentation.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 15.0 * (1.0 / (1.0 + diff));
        }

        // Favor bins that align with the current average residual to keep bins uniform.
        let mean_diff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * mean_diff;

        // If this is the last chance to fit the item in an existing bin,
        // provide a slight discount to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Progression weight: In late stages, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
