            score += diff * 0.5;
        }

        // 4. Balance the load: Favor bins that are already closer to the mean_residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. If this is the last chance for this item (fitting_bins_count == 1), 
