}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    // Penalize small residuals (near 0) that are likely to become unusable "dead space"
    // by applying a non-linear penalty for residuals < 10.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 / (post_residual as f64 + 1.0)
    } else {
        0.0
    };

    // Interaction term: As the stream nears the end, we become more conservative about
    // opening new bins. We bias towards filling existing bins more aggressively.
    let completion_bias = (1.0 - progress) * (open_bins_count as f64 * 0.5);

    // Lookahead logic: If the next item is large, favor bins that leave enough space 
    // for it (if post_residual >= next_item_size).
    let lookahead_score = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else if next_item_size > 0 && post_residual < next_item_size {
        10.0 * progress
    } else {
        0.0
    };

    // New bin logic: If this is an empty bin (bin_residual == bin_capacity), 
    // calculate a baseline cost to open a new bin. 
    // Only open if current fitting bins are extremely inefficient (high mean_residual).
    let new_bin_cost = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Only open new if the mean residual of existing bins is already quite high
            // indicating we are currently fragmenting space poorly.
            45.0 + (mean_residual * 0.8) - (progress * 10.0)
        }
    } else {
        0.0
    };

    let mut score = post_res + dead_space_penalty + completion_bias + lookahead_score + new_bin_cost;

    // Apply a non-linear scaling to favor tighter packing as the bin fills up
    score -= (1.0 - (post_res / bin_capacity as f64)).powi(2) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
