pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to keep bins tight, but penalize "dead zones" (gaps < 10).
    // An empty bin (bin_residual == bin_capacity) is treated as a fallback only if no other bin fits well.

    let mut score = post_residual as f64;

    // 1. Penalize unusable gaps: If post_residual is in [1, 9], it's likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid leaving a small post_residual.
    // If we have a next item, check if it fits in the current post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0; // Reward bins that can accommodate the next item.
    }

    // 3. Open bins pressure: If we have many open bins, penalize opening a new one.
    // If this is a new bin (bin_residual == bin_capacity), increase its score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If other bins can fit this item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already closer to being full (lower mean_residual).
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual (tightest fit).
    // We treat new bins (bin_residual == bin_capacity) with a penalty to discourage opening new bins
    // unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 35.0; 
    }

    // 2. Lookahead matching: If the post_residual is close to the next_item_size, we reward this bin
    // because it creates a "perfect" follow-up opportunity.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward tight matches between residual and next item
        score -= (100.0 - diff) * 0.4;

        // Penalize if the next item cannot fit in the remaining space
        if post_residual < next_item_size {
            score += 15.0;
        }
    }

    // 3. Mean residual balancing: Penalize bins that deviate significantly from the mean_residual
    // to keep bins balanced and avoid "fragmented" bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 4. Scarcity/Pressure: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progress-based scaling: As the stream nears completion, become more aggressive
    // about filling existing bins to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy:
    // 1. Base cost is post_residual (Best Fit logic).
    // 2. Penalize "near-empty" new bins unless the current bin fit is extremely poor.
    // 3. Utilize lookahead (next_item_size) to favor leaving space for future large items.
    // 4. Incorporate global state (mean_residual) to balance bin load.

    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (bins are empty)
        // or if we have very few items left (avoiding new bins near the end).
        let progress = step_index as f64 / total_items as f64;
        score += 15.0 + (mean_residual * 0.5) + (progress * 20.0);
    } else {
        // Reward placements that result in "tight" fits (post_residual near 0)
        // but penalize them if they create a "fragment" too small for future items.
        if post_residual < 10 {
            score -= 5.0; 
        }

        // Lookahead adjustment: If next_item_size exists, prioritize bins that can 
        // accommodate both current and next items if possible, or penalize 
        // bins that would be unable to fit the next item if placed here.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 10.0; // Strong reward for keeping space for next item
            } else if post_residual > 0 && post_residual < 10 {
                score += 8.0;  // Penalty for creating a 'dead' fragment
            }
        }
    }

    // Favor bins that are already closer to the mean residual to keep packing uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // Last chance logic: If this is the only bin that fits, heavily favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We penalize very small residuals (dead space) that cannot accommodate typical future items.
    // A residual of 0 to 9 is often "dead" as items are >= 10.
    let dead_space_penalty = if post < 10.0 && post > 0.0 { 
        (10.0 - post) * 5.0 
    } else { 
        0.0 
    };

    // Lookahead interaction: If the next item is large, prioritize bins that leave 
    // enough space for it, or conversely, if the next item is small, 
    // prioritize bins that are already tight.
    let lookahead_alignment = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            // Reward bins that can accommodate the next item
            -15.0 * (1.0 - progress)
        } else {
            // Penalize bins that cannot accommodate the next item
            10.0 * progress
        }
    } else {
        0.0
    };

    // Global state optimization:
    // As the stream progresses, prioritize closing bins (lower open_bins_count)
    // by penalizing the creation of new bins (when bin_residual == bin_capacity).
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Coupling: Use the deviation from mean_residual to avoid uneven packing
    let variance_penalty = (post - mean_residual).abs() * 0.5;

    let score = post 
        + dead_space_penalty 
        + lookahead_alignment 
        + new_bin_penalty 
        + variance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize small residuals that cannot accommodate common future item sizes.
    // We target "dead space" by penalizing residuals that are smaller than the next item if it's large.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Bin Consolidation: If this is the only bin that fits the item, highly prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 3. Modulo Alignment: Favor residuals that align with common factors of the capacity (100).
    // Residuals like 0, 20, 25, 50 are "cleaner" for future packing.
    let residual_mod = post_residual % 25;
    score += residual_mod as f64 * 0.8;

    // 4. Density Balancing: If we have many open bins, penalize opening a new one 
    // unless the fit is extremely efficient (post_residual near 0).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64 * 2.0);
        // Only open a new bin if the item is large or the mean residual is already high
        if item_size < 50 && mean_residual > 30.0 {
            score += 40.0;
        }
    } else {
        // Favor tighter fits in existing bins
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. Progression Scaling: As the stream nears completion, prioritize closing bins
    // by being more aggressive with fitting items into existing, nearly-full bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

