        // If there are other bins that could fit this item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness objective: Favor bins where the post_residual is small (Best Fit).
    // The base score (post_residual) already helps here, but we normalize by the mean_residual
