    if post_residual as f64 > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if an existing one fits
            score += 150.0 + (mean_residual * 2.0);
        }
        return score;
    }

    // 2. Best-Fit Decreasing logic: Favor bins that leave minimal space
    // We already have post_residual in score, which rewards small gaps.

    // 3. Lookahead Matching (The "Tight-Fit" bonus)
    // If post_residual is close to the next_item_size, we reward this bin
    // to preserve future capacity for larger items.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements where the remaining space is slightly larger than the next item
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize creating a gap that is too small for the next item (fragmentation)
            score += 50.0;
        }
    }

    // 4. Mean Residual Balancing
    // If this bin's post_residual is significantly lower than the global mean,
    // it's a "tight" bin. We want to pack tight bins tightly.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Urgency factor
    // As the stream progresses, be more conservative about opening new bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. Smaller post-residual is usually better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a "fragmented" bin: if remaining space is small but not zero,
    // it's hard to fill later. We penalize residuals in the [1, 15] range.
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_residual as f64) * 2.5;
    }

    // Lookahead logic: if we know the next item, prioritize bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can hold the next item
        } else {
            score += 5.0;  // Penalize bins that will force a new bin for the next item
        }
    }

    // Global state weighting: adjust behavior based on how crowded the bins are.
    // If mean_residual is low, bins are tight; avoid opening new bins unless necessary.
    if is_new_bin {
        // Penalty for opening a new bin is dynamic: higher when bins are already sparse.
        let openness_penalty = (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
        score += openness_penalty;

        // As we approach the end of the stream, be more conservative about opening new bins.
        score += progress * 20.0;
    } else {
        // If this is the only bin that fits the current item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // Adjust score to favor bins that are already well-filled to minimize the number of active bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
