    // Best-Fit Decreasing (BFD) logic: Prefer bins that result in the smallest post_residual.
    // We adjust this based on the lookahead (next_item_size).
    if next_item_size > 0 {
        // If the current post_residual can fit the next item, reward this bin heavily.
        if post_residual >= next_item_size {
