        } else {
            // If it cannot fit, penalize based on how much space is left "stranded".
            score += (100.0 - post_residual as f64) * 0.1;
        }
    }

    // Harmonic constraint: Penalize bins that leave a remainder that is a bad divisor of 100.
    // We want to keep residuals that are multiples of 20 or 25 to maximize future packing.
    let remainder_mod = post_residual % 20;
    if remainder_mod > 5 && remainder_mod < 15 {
        score += 15.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the penalty of placing in existing bins (represented by high residuals) is worse.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of open bins is already quite high,
        // or if we have very few options (fitting_bins_count is low).
        if mean_residual < 20.0 && fitting_bins_count > 0 {
            score += 100.0; // Heavily discourage opening new bins prematurely.
        } else {
            score -= 10.0; // Allow opening new bins if current ones are cluttered.
        }
    }

    // Dynamic scaling based on progression: as we near the end of the stream, 
    // be more aggressive about packing tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
