pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) quadratically
    // A residual of 0 is perfect (score 0), a residual of 1-5 is very bad (dead space)
    let dead_space_penalty = if post_residual > 0 && post_residual <= 5 {
        25.0 / (post_residual as f64).powi(2)
    } else {
        0.0
    };

    // Reward bins that keep us close to the global mean residual (maintains balanced packing)
    let balance_penalty = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: If the next item is large, prioritize keeping space open.
    // If the next item is small, prioritize tight fits.
    let lookahead_mod = if next_item_size > 0 {
        let fit_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        (next_item_size as f64 / 100.0) * (1.0 - fit_next) * 15.0
    } else {
        0.0
    };

    // Late game bias: discourage opening new bins as the stream nears completion
    let new_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 20.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Criticality: If this is the only bin that fits, prioritize it heavily
    let urgency_bonus = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -20.0
    } else {
        0.0
    };

    // Base score: Post-residual (Best Fit principle)
    // Non-linear coupling: Combine base fit with the dynamic penalties/rewards
    let mut score = post + dead_space_penalty + balance_penalty + lookahead_mod + new_bin_penalty + urgency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
