    // but large enough to exist (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the remaining space,
    // reward this placement.
    if next_item_size > 0 {
        let gap_diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += gap_diff * 0.5;
    }

    // 3. Open Bin Pressure: If fitting_bins_count is 1, we are at a critical juncture.
    // Discourage opening a new bin (where bin_residual == bin_capacity) unless the fit is catastrophic.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
