    // We penalize larger post_residuals to encourage tight packing.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: If post_residual is small, it creates "dead space" that is hard to fill.
    // We penalize residuals that are too small to fit the typical minimum item size (assume ~10).
    if post_residual > 0 && post_residual < 10 {
