    }

    // 3. Lookahead Synergy: If the next item fits perfectly into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Fragmentation Control: Avoid opening a new bin if the item could fit elsewhere.
    // If this is a new bin (bin_residual == bin_capacity) and other bins can fit the item, penalize heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
