    // 5. Global Balance: If we have many open bins, penalize the new bin creation even more to force consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 6. Mean Residual Calibration: If this bin's post_residual is significantly better than the current mean, reward it.
    if (post_residual as f64) < mean_residual {
