    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 * (1.0 - progress);
    }

    // 3. Global State: If we have many open bins, encourage consolidation (Best-Fit).
    // If we have very few, be more aggressive with space usage.
    let consolidation_factor = (open_bins_count as f64) * 2.5;
    score += consolidation_factor;

    // 4. Handle the "New Bin" candidate:
    // If bin_residual == bin_capacity, this is a fresh bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if we have too many bins already
        // and we want to preserve tight bins for smaller future items.
        if item_size > 70 {
            score -= 10.0;
        } else {
            // Otherwise, heavily penalize opening a new bin to force packing into existing ones.
            score += 60.0;
        }
    }

    // 5. Fitting constraints: If this is the last chance to fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 6. Mean residual balancing: Penalize bins that deviate significantly from the mean,
    // encouraging a uniform distribution of fill levels.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish high post_residual (Best Fit principle)
    // We prefer post_residual to be small (close to 0).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, the cost of opening a new bin should be balanced 
    // against the potential for future "better" fits.
    if is_new_bin {
        // Penalty scales with how many bins we already have and how much space is wasted on average.
        // We add a steep cost to opening a new bin early.
        score += 85.0 * (1.0 - progress * 0.5) + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, favor placements that leave the residual 
        // closer to the mean_residual of other bins to maintain uniformity.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // Lookahead heuristic: If the next item exists, penalize residuals 
        // that are too small to fit the next item (creating "dead" space).
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            }
        }
    }

    // If this is the only bin that can fit the item, prioritize it heavily 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Non-linear coupling: Exponential growth of penalty for very small residuals 
    // that are likely to become stranded (less than 10, the min item size).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powf(2.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins where post_residual is minimal (tightest fit).
    // The base score is already post_residual, so we punish deviations from tight packing.

    // 2. Harmonic/Modulo Penalty: penalize post_residuals that are small but unusable 
    // for common item sizes (10, 20, 25, 33, 50).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead synergy: if the next item fits into the current post_residual, 
    // reward this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
