    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Strong deterrent against opening new bins prematurely.
        }
    }

    // 5. Global efficiency: If we are late in the stream, be more aggressive 
    // with packing to reduce the total bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 6. Mean-residual balancing: If the current bin's residual after placement 
    // is significantly better than the global mean, reward it to keep bins uniform.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
