    // Lookahead logic: If the next item can fit in the remaining space (post_residual),
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it leaves very little space after the next item
        if (post_residual - next_item_size) < 5 {
