    // Heuristic for opening new bins:
    // Only open a new bin if the current bin is "too full" to be useful for future items,
    // or if we are at the beginning of the stream.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Always open the first bin
        } else {
            // Penalize opening a new bin unless the existing ones are very tight (below average)
            score += 30.0 + (mean_residual * 0.5);

            // If we have many fitting bins, don't open a new one
            score += (fitting_bins_count as f64) * 10.0;
        }
    }

    // Adaptive scaling based on progress: 
    // Towards the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: "Lookahead-Aware Best-Fit with Adaptive Thresholding"

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (tiny gaps that are hard to fill).
    // Specifically, gaps between 1 and 9 are extremely difficult to fill given the input distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead logic: If the next item can fit into the resulting post_residual space, 
    // reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
