    }

    // 3. Dynamic Thresholding: As the stream progresses, become more conservative about 
    // opening new bins. If it's a new bin (bin_residual == bin_capacity), penalize it 
    // increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 30.0);

        // If we are late in the stream and have many open bins, penalize new bin creation.
        if progress > 0.7 && open_bins_count > 5 {
            score += 40.0;
        }
    }

    // 4. Global State Awareness: If there are very few bins that can fit this item, 
    // prioritize using one of them to avoid fragmentation.
    if fitting_bins_count > 0 && fitting_bins_count < 3 {
        score -= 15.0;
    }

    // 5. Mean residual balance: Avoid bins that deviate significantly from the global mean residual.
    // This helps keep bins packed at similar densities.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as they are hard to fill.
    // We use a sigmoid-like penalty for small post_residuals.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        100.0 / (post_res + 1.0)
    } else {
        0.0
    };

    // Favor bins that leave enough room for the lookahead item if it exists.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Discourage opening new bins early in the stream unless the fit is perfect.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Heavily penalize opening a new bin if we have fitting options
            40.0 + (progress * 60.0)
        }
    } else {
        0.0
    };

    // Combine objective: 
    // 1. Minimize post_residual (Best Fit principle).
    // 2. Add penalties for dead zones and suboptimal new bin creation.
    // 3. Incorporate mean_residual to balance packing density across open bins.
    let score = post_res 
        + gap_penalty 
        + lookahead_penalty 
        + new_bin_bias 
        + (mean_residual * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in [1, 9], it's dangerous, penalize exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Density Balancing: If the bin is becoming too empty, penalize opening it if others are available.
    // Use mean_residual to detect if we are spreading items too thin.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. Harmonic Class Logic: Prefer filling bins to high capacity (modulo 20 thresholds).
    // Bins with residuals near 0, 20, 40, etc., are statistically more versatile.
    let remainder = post_residual % 20;
    if remainder < 5 {
        score -= 10.0;
    } else if remainder > 15 {
        score += 15.0;
    }

    // 6. Progressive Tightening: As the stream nears completion, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

