        score += 20.0 + (completion_ratio * 40.0);

        // Penalize opening new bins if there are already many open bins 
        // that could potentially accommodate items.
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean Residual Alignment: Reward bins that keep us close to the mean,
    // preventing the creation of extreme outliers in bin fullness.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

