    // 2. Lookahead optimization: If the post_residual is close to the next_item_size, we reward this bin.
    // We favor placements that leave a residual that can perfectly or nearly perfectly accommodate the next item.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        score -= (100.0 - diff) * 0.25;
    }

    // 3. Penalty for fragmentation: If the post_residual is small but not zero (a "sliver"), 
    // it is often harder to fill later. We penalize residuals in the [1, 10] range.
    if post_residual > 0 && post_residual < 12 {
        score += 15.0;
    }

    // 4. Global state awareness: If we have many open bins, we become more aggressive about 
    // filling existing bins (Best-Fit behavior) to consolidate space.
    if open_bins_count > 5 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
