    }

    // 6. Mean residual balancing: Penalize placing in bins that are already significantly 
    // fuller than the average, to maintain a balanced distribution of space.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
