}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize post_residual to pack tightly.
    let mut score = post;

    // Penalty for creating a "dead zone" (very small residual that cannot fit common items)
    // We penalize residuals in the [1, 9] range heavily as they are likely unusable.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize leaving enough space for it.
    // If the next item is large (e.g., > 60), avoid bins where post_residual is slightly less than next_item_size.
    if next_item_size > 50 {
        if post > 0.0 && post < (next_item_size as f64) {
            score += 30.0 * (1.0 - (post / next_item_size as f64));
        }
    }

    // Dynamic adjustment based on stream progression.
    // Near the end of the stream, prioritize closing bins (minimize open_bins_count).
    // We apply a non-linear scaling factor to the mean_residual interaction.
    let exhaustion_factor = progress.powf(2.0);
    score += exhaustion_factor * (mean_residual - post);

    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we lower the score to strongly encourage using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New bin candidate handling:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We increase its score to make it less attractive than filling existing bins,
    // unless the existing bins result in very poor packing (very high post_residual penalty).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

