    // 3. New Bin Threshold: If this is a new bin, penalize it relative to the fitting_bins_count.
    // Only open a new bin if the existing fits are extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0;
        }
    }

    // 4. Distributional Balancing: Use mean_residual to prevent uneven bin usage.
    // If this bin is much fuller than the average, penalize it to encourage balancing.
    let current_usage = bin_capacity - bin_residual;
    let avg_usage = bin_capacity - mean_residual;
    if current_usage > avg_usage as u32 {
        score += (current_usage - avg_usage as u32) as f64 * 0.5;
    }

    // 5. Modulo-based Harmonic Classing:
    // Reward packing into buckets of 20 to keep residuals aligned for larger items.
    let mod_val = post_residual % 20;
    if mod_val == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
