    // 5. Global Efficiency: If the post_residual is very close to the mean_residual of other bins,
    // it keeps the bin distribution uniform, which is generally efficient for packing.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Progress Scaling: As the stream nears the end, prioritize closing bins (lower residual)
    // to avoid leaving partially filled bins at the end of the sequence.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Penalize large post_residuals (wasted space)
    // We favor bins where post_residual is as small as possible.

    // 2. Lookahead matching: If post_residual is close to next_item_size, we reward it.
    // This creates "perfect fit" chains.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 * (1.0 / (1.0 + diff));
    }

    // 3. Prevent fragmentation: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin call.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Pressure management: If fitting_bins_count is 1, we are at risk of losing this bin
    // to a bad fit. We adjust the score to ensure we don't leave it too empty.
    if fitting_bins_count == 1 && post_residual > 20 {
        score += 15.0;
    }

    // 5. Mean-based balancing: Penalize bins that deviate too much from the current mean_residual.
    // This promotes uniform distribution of space across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // 6. Final progression adjustment: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

