    // Penalize large post_residual to encourage tight packing
    score += post_residual as f64 * 0.5;

    // 2. Lookahead logic: if next item exists, penalize bins that cannot fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 3. Global state: discourage opening new bins unless necessary
    if is_new_bin {
        // Only open a new bin if the current mean residual is already quite low
        // or if we are nearing the end of the stream
        score += 45.0 + (mean_residual * 0.2);
        if progress > 0.9 {
            score -= 10.0;
        }
    }

    // 4. Criticality: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 5. Dynamic penalty for fragmentation
    // If post_residual creates a "dead zone" (too small for most items), penalize
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Slivers are small residuals that are unlikely to fit future items.
    // We penalize post_residual ranges [1, 9] heavily, especially early in the stream.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (2.0 + 5.0 * (1.0 - progress));
    }

    // Heuristic: If this is a new bin, penalize it based on how many existing bins
    // could have taken the item. Opening a new bin is a last resort.
    if is_new_bin {
        score += 15.0 + (fitting_bins_count as f64 * 10.0);
    } else {
        // Favor bins that bring the residual closer to the global mean (tight packing)
        score += (post_residual as f64 - mean_residual).abs() * 0.5;
    }

    // Lookahead logic: If we know the next item, penalize bins that cannot accommodate it
    // if we are nearing the end of the stream (where packing efficiency matters more).
    if next_item_size > 0 && !is_new_bin {
        if post_residual < next_item_size {
            score += 5.0 * progress;
        }
    }

    // Adjust for the total number of open bins to encourage consolidation
    score += (open_bins_count as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments too small for common item sizes)
    // We penalize post_residuals that are small but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Harmonic alignment: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This maximizes the chance of fitting future items perfectly.
    if post_residual % 20 == 0 {
        score -= 15.0;
    }

    // Lookahead logic: If the next item is large, prioritize keeping space open.
    // If next_item_size is large, we want a post_residual that is either 0 or >= next_item_size.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 40.0; // Avoid fragmenting space needed for the next item
        } else if post_residual >= next_item_size {
            score -= 10.0; // Reward bins that can accommodate the next item
        }
    }

    // Global state awareness: If we are nearing the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 5 {
        score -= 20.0;
    }

    // New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    // Only open a new bin if the best existing bin has a poor fit (post_residual is large).
    if bin_residual == bin_capacity {
        score = 65.0; // Base cost to open a new bin
    } else {
        // Encourage Best-Fit behavior by penalizing large post_residuals in existing bins
        score += post_residual as f64 * 0.5;
    }

    // Discourage opening new bins if there are plenty of fitting bins available
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with dead-space penalty and bin-count regularization.
    // We prioritize bins that result in a post_residual of 0 (perfect fit).
    // We heavily penalize post_residuals that fall into the "unusable" range (1-9).
    // If we are forced to open a new bin, we apply a pressure penalty based on open_bins_count.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in (0, 10), it is likely unusable.
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item can fit in the current post_residual, reward it.
    if !is_new_bin && next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. New Bin Penalty: Only open a new bin if the current open bins are all very poor fits.
    // We scale the cost of opening a new bin by the current number of open bins to prevent fragmentation.
    if is_new_bin {
        score = 45.0 + (open_bins_count as f64 * 2.5);

        // If there are other bins that could fit this item, make opening a new one very expensive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: Encourage filling bins that are already closer to capacity.
    if !is_new_bin {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
