        // Increase penalty as we approach the end of the stream to force tighter packing
        score += (progress * 40.0);
        // If we have many open bins, penalize opening another one
        score += (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that bring the residual closer to the global mean (balancing)
        let diff = (post_residual as f64 - mean_residual).abs();
