        // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 4. Tightness reward: Favor bins that leave very little space
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
