    }

    // Global balance: penalize creating too many open bins relative to the mean residual.
    // If our current bin's residual is significantly worse than the mean, penalize it.
    if !is_new_bin && (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

