    // Use bin_residual to identify "fuller" bins (low residual).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless fitting_bins_count is 0 (meaning we have no choice).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if there are existing options
            score += 65.0;
        } else {
            // We must open a new bin, so normalize the score
            score = 0.0;
        }
    }

    // 5. Progression Adjustment: As the stream nears completion, become more aggressive 
    // about packing into existing bins to avoid leftover bin overhead.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

