        score -= mean_residual * 0.2; 
    }

    // 5. Scarcity Constraint: If this is the only bin that can fit the current item,
    // strongly incentivize using it to avoid forced new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Entropy Reduction: Penalize configurations that deviate significantly from the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We apply non-linear transformations to penalize "bad" residuals based on stream phase.
    let mut score = post;

    // Penalty for creating small, unusable gaps (dead space < 10)
    // We amplify this penalty as the stream progresses to consolidate bins later.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + 2.0 * progress);
    }

    // Lookahead logic: if the next item could fit in this post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // Discourage opening new bins unless necessary (fitting_bins_count == 0).
    // If it's a new bin (bin_residual == bin_capacity), apply a heavy progress-based tax.
    if bin_residual == bin_capacity {
        // Only consider new bin if we have no other choice or if the progress is early.
        // We add a penalty that grows with the number of open bins to discourage fragmentation.
        score += 15.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0);
    } else {
        // If it's an existing bin, favor those that move the mean_residual 
        // closer to the expected average item size (approx 40).
        let deviation = (post - (bin_capacity as f64 * 0.4)).abs();
        score += deviation * 0.1;
    }

    // Final dampening: favor bins that are already "half-full" to maintain uniform density.
    score += (bin_capacity as f64 - bin_residual as f64 - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
