    // 4. Harmonic scaling: penalize bins that deviate significantly from the mean residual
    // to keep the distribution of remaining space uniform across bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 5. New bin logic:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold cost.
    // This value represents the "cost of opening a new bin".
    if bin_residual == bin_capacity {
        // We only open a new bin if the best existing fit is still quite poor.
