pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We scale this by a factor to ensure it remains the primary driver.
    score *= 1.0;

    // 2. Lookahead matching: If the post_residual can perfectly fit the next item, 
    // provide a massive reward (negative score).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fit for the next item; lower diff is better.
        score -= (100.0 - diff) * 2.5;
    }

    // 3. New bin thresholding: If this is an empty bin, penalize it based on how many
    // open bins are available. If many bins are open, we prefer packing into existing ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If it's the only option, reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // 4. Fragmentation avoidance: Penalize bins that would fall below the mean residual
    // unless they fit the next item perfectly.
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    }

    // 5. Urgency: As we reach the end of the stream, prioritize closing bins 
    // (tightening the fill) over keeping many bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space) 
    // but weigh it against the number of currently open bins.
    score += (post_residual as f64).powf(1.2) * (1.0 + 0.5 * (open_bins_count as f64).ln());

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding: Discourage opening a new bin unless the current 
    // average residual is high or we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 25.0 && progress < 0.95 {
            score += 150.0; // Heavy penalty for opening new bins prematurely
        } else {
            score -= 10.0; // Allow new bins if existing ones are inefficiently packed
        }
    }

    // 4. Criticality Adjustment: If this is the only bin that can fit the item, 
    // reduce penalty to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency Balancing: Penalize bins that deviate significantly 
    // from the mean_residual to promote uniform bin usage.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    } else {
        // Penalty for fragmentation: 
        // We penalize post_residual exponentially if it creates a small, unusable gap (e.g., < 10)
        // especially when we have many bins open.
        if post_residual > 0 && post_residual < 15 {
            score += 15.0 * (1.0 - (post_residual as f64 / 15.0));
        }

        // Lookahead heuristic: 
        // If the next item is large, prioritize bins that can accommodate it.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                score += 10.0 * (1.0 - progress);
            }
        }

        // Dynamic load balancing:
        // Penalize bins that deviate significantly from the mean residual of open bins
        // to encourage packing bins to a similar level of fullness.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Fitting constraint:
    // If this is the only bin that fits the item, highly prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: If post_residual is a multiple of common item sizes, 
    // it's more flexible. Penalize remainders that break symmetry.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Synergy: If the next item fits perfectly into the post_residual, 
    // reward this bin choice significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff < 5.0 {
            score -= 40.0 - diff;
        }
    }

    // 4. Thresholding: Avoid opening a new bin unless the current mean_residual 
    // is extremely tight or the current item is very large.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only open if the average slack in existing bins is already very low.
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 100.0;
        } else {
            score += 30.0;
        }
    }

    // 5. Progression awareness: As the stream nears completion, 
    // strictly prioritize packing to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Last-chance logic: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical items (e.g., < 10)
    // but large enough to waste space. We define "unusable" range as [1, 9].
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening new bins when existing ones could work.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if other bins can fit the item
            score += 150.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If no other bins fit, prioritize the new bin but normalize cost
            score = 25.0;
        }
    }

    // 3. Lookahead coupling: If next_item_size exists, penalize post_residuals that 
    // effectively "kill" the ability to fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a gap that cannot fit the immediate successor
            score += 20.0;
        } else {
            // Reward creating a gap that can fit the immediate successor
            score -= 10.0;
        }
    }

    // 4. Global efficiency: Favor bins that stay closer to the mean_residual
    // This promotes packing density uniformity across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression scaling: As we reach the end of the stream, be more aggressive
    // about closing bins (higher penalty for opening new ones).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Favor tight packing: If post_residual is small, it's generally good.
    // However, if post_residual is exactly next_item_size, it's a perfect match.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
        if post_residual == next_item_size {
            score -= 50.0; // Strong reward for perfect lookahead match
        }
    }

    // 2. Avoid "Dead Space" creation: Penalize post_residual if it's too small to fit 
    // any likely future items (e.g., < 15) unless it perfectly closes a bin.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0; 
    }

    // 3. New Bin Penalty: If this is a new bin (residual == capacity), penalize it 
    // based on how many other bins could have accepted this item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0 + (fitting_bins_count as f64 * 10.0);
        }
    }

    // 4. Global State Awareness: If we have many open bins, penalize creating 
    // a new one or picking a bin that deviates significantly from the mean_residual.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 5. Progression Weighting: As we approach the end of the stream, 
    // be more aggressive about closing bins (reducing score for lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prefer tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is almost empty but not quite full enough to be useful
    // If post_residual is in the "dead zone" (e.g., 1-10), penalize it
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state: If we have many open bins, prioritize clearing those with low residuals
    // If we have very few open bins, be more conservative about opening new ones
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how many items remain
        // Higher penalty early on to force consolidation
        score += 15.0 + (1.0 - progress) * 20.0;

        // If there are other bins that could fit the item, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    } else {
        // Reward bins that bring the mean residual closer to a target value (e.g., 15-20)
        // This encourages "packing" rather than leaving many half-empty bins
        let diff = (post_residual as f64 - 15.0).abs();
        score += diff * 0.5;
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize space efficiency over consolidation
    if progress > 0.9 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual).
    // Penalize higher post_residual quadratically to avoid fragmentation.
    let mut score = post_res.powf(1.5);

    // Interaction: Lookahead penalty. If next_item_size is large and won't fit in the
    // remaining post_residual, apply a penalty proportional to the potential mismatch.
    if next_item_size > 0 {
        let next_penalty = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 1.2
        } else {
            -(post_residual - next_item_size) as f64 * 0.5
        };
        score += next_penalty;
    }

    // Dynamic opening threshold: As we approach the end of the stream, be more conservative
    // about opening new bins. If current bin is empty (new bin candidate), penalize it 
    // based on how many open bins already exist.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: bias against it early, but allow if
        // existing bins are too full to accommodate future items.
        score += 45.0 + (open_bins_count as f64 * 2.0 * (1.0 - progress));
    } else {
        // If the bin is already open, reward bins that are closer to the mean_residual
        // to keep usage distribution uniform, helping to prevent high-residual "dead" bins.
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.3;

        // If this is the only bin that fits, give it a strong preference boost.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // The base score is already post_residual, which inherently favors tightest fit.

    // 2. Harmonic Class Logic: Penalize creating "unusable" small gaps.
    // If the post_residual is less than the smallest expected item (10), 
    // it is highly likely to be wasted. Penalize this heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead Sensitivity: If next_item_size is large, avoid small post_residuals.
    // If we have a large item coming, we need a bin that can accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placing current item here if it blocks the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 4. Thresholding: Avoid opening a new bin unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a heavy "activation cost"
    // unless the current fitting options are extremely poor (i.e., they create high waste).
    if bin_residual == bin_capacity {
        score += 35.0;

        // If we have many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 5. Global Efficiency: Balance the number of bins.
    // If the mean_residual is already low, we are packing tightly; be more conservative.
    if mean_residual < 20.0 {
        score += (20.0 - mean_residual) * 0.5;
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    // favor finishing existing bins (lower penalty for small residuals).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Heavily penalize post_residuals that are too small to fit any likely future items (e.g., < 10).
    // If we leave a gap between 1 and 9, it is likely "dead space" unless the item is very small.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Best-Fit logic: Prefer bins where the post_residual is minimized (Best-Fit principle).
    // The base score already accounts for post_residual, but we refine it.

    // 3. Lookahead Synergy: If the next item fits perfectly into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. Open Bins Pressure: Penalize opening a new bin if we have many open bins.
    // If this is a new bin (bin_residual == bin_capacity), increase the score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If there are other bins that could fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Fragmentation control: If the mean_residual is high, we are under-utilizing bins.
    // Penalize placements that increase the mean_residual significantly.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 6. Final normalization: Ensure that filling a bin completely (post_residual == 0) is highly rewarded.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for empty bins: prioritize filling existing bins over opening new ones
    // unless the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 2. Lookahead matching: if the post_residual can accommodate the next item, 
    // significantly reward this bin choice to consolidate space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
        // Bonus for "perfect" fits (exact matches)
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Penalty for fragmentation: penalize bins that leave space too small to be useful 
    // for future items (e.g., < 10, since min item size is likely around 10-15).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 4. Mean-residual balancing: favor bins that keep the overall average residual low,
    // discouraging the creation of "outlier" bins that deviate heavily from current utilization.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Urgency factor: If this is the only bin that fits the current item, 
    // force its selection to avoid unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive packing: As we near the end of the stream, prioritize tighter packing
    // to minimize the tail-end bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor bins where the remaining space is small (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // we heavily prioritize this bin to conserve bin count.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Thresholding: Prevent opening a new bin if the current bin
    // has a decent fit, unless the current bin is excessively empty and
    // the item is large (fragmentation avoidance).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to progress.
        // As the stream nears completion, we become more conservative about opening new bins.
        score += 25.0 * (1.0 - progress);

        // If it's a new bin, penalize if it's not a "tight" fit for the item.
        score += (bin_capacity - item_size) as f64 * 0.2;
    } else {
        // 4. Global State Balancing: If we have many open bins with high mean residuals,
        // we should try to fill the current bin to consolidate space.
        if mean_residual > 30.0 {
            score -= (bin_capacity - bin_residual) as f64 * 0.3;
        }

        // 5. Criticality check: If this is the only bin that can fit the item,
        // prioritize it regardless of post_residual score.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Dynamic Scaling: Favor tighter packing as the stream progresses.
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to have 0 than a useless small gap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: If the next item is large, penalize bins that cannot fit it
    // after the current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Stream progression adjustment: As we reach the end of the stream, 
    // become more aggressive about filling existing bins to avoid new openings.
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        score -= 20.0 * progress;
    }

    // Penalty for opening a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the number of open bins and progress.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    }

    // Mean residual coupling: penalize bins that deviate significantly from the average
