    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Coupling: 
    // If the post_residual is small, it creates "dead space" that cannot fit common items.
    // We penalize post_residuals that are in the range [1, 9] as they are rarely useful.
    if post_residual > 0 && post_residual < 10 {
