    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress.
        // Opening a bin early is cheap, opening late is expensive.
        score += 25.0 + (progress * 40.0);

        // If we have many fitting bins, don't open a new one.
        if fitting_bins_count > 0 {
            score += 100.0 * (fitting_bins_count as f64);
