    if (bin_residual as f64) > mean_residual {
        score -= 10.0;
    }

    // 5. If this is the only bin that fits, prioritize it heavily to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Reward bins that result in a tight fit (residual close to 0)
    // especially for larger items.
    if post_residual < 5 {
