    score += (post_residual as f64) * 0.5;

    // 2. Harmonic Class logic: penalize residuals that are not multiples of common item sizes (10, 20, 25)
    // We want to leave space that is likely to be filled by the next item or common sizes.
    let harmonic_penalty = if post_residual > 0 {
        let rem = post_residual % 10;
        if rem == 0 { -5.0 } else { rem as f64 * 2.0 }
    } else {
        -20.0 // Reward perfect fills
    };
    score += harmonic_penalty;

    // 3. Lookahead coupling: If post_residual cannot fit the next item, penalize significantly
    if next_item_size > 0 && post_residual < next_item_size {
