    }

    // 5. New Bin Penalty: If the bin is brand new (residual == capacity), add a high cost.
    // This forces the algorithm to prefer filling existing bins unless the fit is catastrophic.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Progression scaling: As we approach the end of the stream, prioritize bin exhaustion
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

