    // As the stream progresses, we become more willing to open new bins to maintain high density.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + 20.0
    } else {
        0.0
