    // Best Fit Decreasing logic: heavily favor bins that result in small residuals.
    // Use a quadratic term to punish large gaps that are difficult to fill later.
    let fit_score = post * post / 10.0;

    // Lookahead interaction: if the next item fits into the current post_residual, 
