    // but too large to be considered "tight". If post_residual is in the "dead zone" (1-9),
    // we increase the score to avoid leaving unusable space.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Logic: If next_item_size exists, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only open a new bin if the mean residual is already quite low,
    // indicating that current bins are getting too fragmented.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 10.0;
        } else {
            score += 60.0; // High penalty to force usage of existing bins
        }
    }

    // 4. Fitting Constraint: 
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize filling existing bins
    // to avoid leaving partially filled bins at the end.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
