    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post) * 0.8
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep bin states uniform (load balancing).
    let deviation_penalty = (post - mean_residual).abs() * 0.2;

    // Favor bins that are "almost full" to minimize the number of active open bins,
    // but weigh this against the risk of creating a "sliver" (a very small residual).
    let sliver_penalty = if post > 0.0 && post < 10.0 { 25.0 } else { 0.0 };

    // Combine factors
    // Lower score is better.
    let score = post + new_bin_penalty + lookahead_penalty + deviation_penalty + sliver_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space (dead space < 10, which is the minimum item size)
    // We prioritize bins that leave exactly 0 space or >= 10 space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Class Logic: Reward fitting the next item perfectly into the current post_residual.
    // If the next item fits perfectly into the remaining space, we prioritize this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Penalize leaving space that is too small for the next item
            score += 5.0;
        }
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one heavily.
    // If this is a new bin (bin_residual == bin_capacity), increase cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // If there are other bins that could fit this item, penalize opening a new one further.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Coupling: Encourage filling bins that are already "fuller" than the average.
    // If this bin is below the mean fullness, it's a "cold" bin; penalize it slightly to consolidate items.
    if (bin_capacity - bin_residual) < (bin_capacity as f64 - mean_residual) as u32 {
        score += 10.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins (minimizing post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

