    // for future items (min size 10). Penalize these gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, 
    // reward this placement to keep bin density high.
    if next_item_size > 0 && post_residual >= next_item_size {
