        }
    }

    // 4. Tightness bias: Favor bins that are already nearly full (Best Fit principle).
    // Subtracting a fraction of the residual pushes the score lower for tighter fits.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the mean 
    // residual of other bins to maintain uniform bin states.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
