    // unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin > 0.0 {
        score -= 50.0;
    }

    // Normalize against mean_residual to prevent massive divergence in bin utilization.
    // If current bin is significantly worse than average, penalize it.
    let residual_diff = post_res - mean_residual;
    if residual_diff > 0.0 {
        score += residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
