    // 2. Lookahead interaction: if next_item fits in the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
    }

    // 3. Global state: if we have many bins open, penalize opening a new one.
    if is_new_bin {
        score += (open_bins_count as f64 * 2.5) + (10.0 * progress);
    }

    // 4. Scarcity principle: if this is the only bin that fits the item, make it highly attractive.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. Balance residuals: prefer bins that keep the mean_residual stable.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Dynamic pressure: as we approach the end of the stream, discourage new bins
    // unless the fit is perfect.
    if is_new_bin && progress > 0.8 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
