    // We prioritize bins that result in a small post_residual.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple of 
    // common item sizes or "clean" fractions of the capacity (e.g., 25, 50, 20).
    // This reduces fragmentation by aligning residuals with potential future item sizes.
    let alignment_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += alignment_penalty * 2.0;

