    // to minimize the need for future bins.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good fit for the next item, reward slightly to prioritize this bin.
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Bad fit for the next item, creates a forced new bin, penalize.
            score += 25.0;
        }
    }

    // 3. Open bins pressure:
    // As the total_items progress, penalize opening new bins (bin_residual == bin_capacity).
    // We want to force consolidation into existing bins early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * (1.0 + progress) + (open_bins_count as f64 * 2.0);
    }

    // 4. Fitting constraints:
    // If this is the only bin that can fit the item, we must take it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual equilibrium:
    // Penalize bins that deviate too far from the average residual of open bins 
    // to keep the bin distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize fragmentation: If the post_residual is too small to fit any common item (e.g., < 10),
    // it creates "dead space". We heavily penalize residuals between 1 and 9.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // prioritize this bin to maximize bin density (Best Fit + Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter alignment with the next item
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Adaptive thresholding: If this is the last fitting bin, we are desperate.
    // Discourage opening a new bin by making the current bin very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 4. Global balance: If the current bin is significantly emptier than the average 
    // of all open bins, discourage filling it to keep the "mean_residual" tight.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 5. New bin management: If we are considering a brand new bin (residual == capacity),
    // make it expensive unless we have no other choice or the item is exceptionally large.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item is very large (e.g., > 70), a new bin is less penalized.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // 6. Progression scaling: As we reach the end of the stream, prioritize 
    // closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
