        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // Encourage balancing: penalize bins that deviate too far from the global mean residual
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Final adjustment: if this is the last chance for the item (only 1 bin fits), 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
