        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tight fit reward: If we fill the bin perfectly or nearly perfectly, lower the score.
    if post_residual == 0 {
        score -= 10.0;
    }

    // 5. Global bin consolidation: favor bins that keep the mean_residual low.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We add a quadratic penalty for leaving large gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Lookahead matching: If the next item fits into the current post_residual, 
    // significantly reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further reward if the gap left by the NEXT item is very small
        let post_post = post_residual - next_item_size;
        score += (post_post as f64) * 0.5;
    }

    // 3. New-Bin Constraint: If this is a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 4. Global balance: If we have many open bins, penalize opening more unless necessary.
    // Use the mean_residual to prefer bins that are already "closer" to the average state.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about fitting items into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic augmented with lookahead and bin-density optimization.
    // We aim to minimize the remaining post_residual (Best Fit), but penalize placements
    // that leave the bin in an 'awkward' state where future items (next_item_size) cannot fit.

    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to discourage opening new bins
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is related to the current average waste.
        score = mean_residual * 1.5;

        // If we have many fitting bins, opening a new one is highly inefficient.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 2. Lookahead optimization: If next_item_size exists, penalize post_residual
    // if it makes the bin unable to accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This placement creates 'unusable' space for the immediate future.
            score += 25.0;
        } else {
            // Reward placements that leave room for the next item.
            score -= 10.0;
        }
    }

    // 3. Dynamic progression: As we approach the end of the stream, 
    // become more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 4. Penalize creating very small, hard-to-fill residuals (fragmentation).
    // Residuals < 10 are often 'dead' since items are >= 10.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // 5. If this is the last chance to fit an item in an existing bin,
    // strongly favor this bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility as the stream progresses.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress).powf(0.5) * 40.0 + 10.0
    } else {
        0.0
    };

    // Calculate a "tightness" score: prefer bins where the remaining space is small,
    // but penalize values that are too small to fit common upcoming items.
    // We use next_item_size to modulate the desirability of the post_residual.
    let lookahead_penalty = if next_item_size > 0 {
        if post < next_item_size as f64 {
            // This bin will likely be unable to fit the next item, creating fragmentation.
            (next_item_size as f64 - post) * 0.8
        } else {
            // This bin is perfectly positioned to accept the next item.
            -(post - next_item_size as f64) * 0.2
        }
    } else {
        0.0
    };

    // Use mean_residual to balance the bin landscape. 
    // If our current bin is significantly emptier than the average, we prefer it less (fragmentation risk).
    let deviation_penalty = (bin_residual as f64 - mean_residual).abs() * 0.1;

    // fitting_bins_count logic: if this is the only bin that fits the item, 
    // we should prioritize it significantly to avoid opening a new bin unnecessarily.
    let scarcity_reward = if fitting_bins_count == 1 && !is_new_bin {
        -25.0
    } else {
        0.0
    };

    // Aggregate score: lower is better.
    // Quadratic growth on post_residual to avoid leaving large gaps.
    let base_score = post.powf(1.2);

    base_score + new_bin_penalty + lookahead_penalty + deviation_penalty + scarcity_reward
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // We prioritize bins where the post_residual is small (tight fit).
    // If post_residual is 0, we reward it heavily to encourage perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score += (post_residual as f64).powf(1.2);
    }

    // 2. Lookahead logic: If next_item_size fits in the post_residual, reward this bin.
    // This creates "chains" of items that fill the bin efficiently.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // 3. Fragmentation penalty: Avoid creating small, unusable residuals (< 10).
    // If the post_residual is too small to fit the smallest expected items, penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. New Bin Threshold: Discourage opening new bins unless the current options are very poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, unless the system is already fragmented.
        score += 60.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Harmonic balancing: If a bin is nearly empty, we prefer to fill it rather than
    // spreading items across many bins.
    if bin_residual < bin_capacity / 2 {
        score -= 10.0;
    }

    // 6. Progressive pressure: As we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 40.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
