pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize empty bins exponentially as the stream progresses to favor consolidation
    let open_penalty = if bin_residual == bin_capacity {
        (1.0 - progress).powi(2) * 50.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Best-fit principle: reward smaller post_residual (tighter packing)
    // Non-linear coupling: penalize high residual space relative to the mean_residual
    let residual_efficiency = post_res + (post_res - mean_residual).powi(2) * 0.1;

    // Lookahead: If next_item_size is large, prioritize keeping larger post_residuals 
    // to accommodate the upcoming item, unless we are near the end of the stream
    let lookahead_weight = if next_item_size > 0 {
        let fit_next = (post_residual >= next_item_size) as i32 as f64;
        (1.0 - fit_next) * (next_item_size as f64 * 0.5) * (1.0 - progress)
    } else {
        0.0
    };

    // Final score: lower is better. 
    // We favor bins that fit the current item tightly (residual_efficiency)
    // while managing the cost of opening new bins (open_penalty) 
    // and maintaining flexibility for the next item (lookahead_weight).
    residual_efficiency + open_penalty + lookahead_weight
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation below typical item floor 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can still accommodate it
    if next_item_size > 0 {
