    }

    // Harmonic preference: prioritize filling bins to specific thresholds (e.g., 50, 75, 90)
    // to keep residuals in ranges that match common item size classes.
    let harmonic_penalty = match post_residual {
        0..=5 => -40.0,   // Strong reward for perfect or near-perfect fits
        6..=15 => -10.0,  // Moderate reward for high density
        _ => 0.0,
    };
    score += harmonic_penalty;

    // If bin is new (bin_residual == bin_capacity), penalize opening it unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
