    if progress > 0.9 {
        score += (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit).
    let mut score = post;

    // Penalty for creating "slivers" (very small residual) that are hard to fill later.
    // We penalize post_residual values in the 1..15 range, as they are often unusable.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.5;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // significantly reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamics: As we approach the end of the stream, prioritize packing items tightly
    // into existing bins to minimize the total count, even if it creates slivers.
    // We dampen the sliver penalty as progress increases.
    let sliver_dampening = 1.0 - (progress * 0.8);
    score -= (15.0 - post).max(0.0) * (1.0 - sliver_dampening);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on 
    // how much space is left in existing bins. If we have many open bins with 
    // high mean_residual, opening a new bin is inefficient.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Increase penalty for opening new bins as we progress through the stream.
        score += progress * 50.0;
    }

    // Reward bins that become perfectly full (residual 0).
    if post == 0.0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (minimize wasted space).
    // The base score is post_residual. We modify this to account for packing constraints.

    // 2. Penalty for opening new bins: if current bin is new, add a significant constant
    // unless no other bin can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead Harmonic Coupling:
    // If we have a next item, we want to leave enough room for it.
    // If post_residual is smaller than next_item_size, we create "dead space" that cannot
    // fit the next item. We penalize this based on the size of the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly enough space for the next item (harmonic match).
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Density Balancing:
    // If the mean residual of current bins is high, we are already fragmented.
    // Favor bins that push the residual closer to the mean to consolidate space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 6. Thresholding for "Perfect" fits (Modulo 10 heuristic):
    // If post_residual is a multiple of 10, it is often more flexible for future items.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize dead space (< 10) 
