    }

    // 4. Fitting Bin Scarcity:
    // If this is the only bin that can fit the item, prioritize it to avoid 
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. Mean Residual Alignment:
    // Penalize bins that deviate significantly from the mean residual to keep
    // bin fill levels balanced (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
