    // 3. Fragmentation avoidance: If post_residual is too small for any future items (assuming 10 as lower bound),
    // it creates 'dead space'. We penalize very small residuals that aren't zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Strategic new-bin constraint:
    // If we are forced to pick a new bin (bin_residual == bin_capacity),
    // only do so if the current open bins are 'bad' (mean_residual is low).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // New bin is expensive; penalize heavily if we have room in existing bins.
            score += 60.0;
