        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Reward exact fit (slack 0) and small slack
            score -= 20.0 / (slack as f64 + 1.0);
        } else {
            // Penalize if the current placement makes the next item impossible
            score += 15.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual equilibrium: Avoid spreading items too thin.
    // Penalize if post_residual is significantly lower than the current mean 
    // (tending towards bin exhaustion).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If post_residual is close to next_item_size, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect or near-perfect fit for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 / (1.0 + diff));
        } else {
            // Cannot fit next item, penalize this bin slightly
            score += 15.0;
        }
    }

    // 3. Last-Chance heuristic: If this is the only bin that fits the current item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. Global balance: Avoid fragmentation by favoring bins that stay near the mean_residual
    // This helps keep future items packed into similar space profiles.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev_from_mean;

    // 5. New-Bin Penalty: Only open a new bin if the score is extremely low.
    // The base score for a new bin (bin_residual == bin_capacity) is 100.0.
    if bin_residual == bin_capacity {
        score = 85.0; 

        // If we have many open bins, penalize opening a new one further.
        score += open_bins_count as f64 * 0.5;

        // If we are near the end of the stream, be more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
