    if is_new_bin {
        // If we have other options, penalize opening a new bin heavily, 
        // but soften penalty as we approach the end of the stream.
        score += (bin_capacity as f64) * 0.75 * (1.0 - progress);

        // If an item can fit elsewhere, discourage opening a new bin
        if fitting_bins_count > 0 {
