        }
    }

    // Global state adjustment: balance the load across bins
    // If this bin's residual is much higher than the mean, it's a "loose" bin;
    // prefer tighter bins to keep mean_residual low.
    if !is_new_bin {
        let deviation = (bin_residual as f64) - mean_residual;
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
