    // 2. Harmonic Class logic: Favor residuals that align with common item size multiples (e.g., 20, 25, 33, 50)
    // This reduces fragmentation by encouraging bins to empty completely or reach specific thresholds.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead integration: If next_item_size is large, prioritize bins that can accommodate it.
    // If the current post_residual is slightly smaller than next_item_size, it's a "near-miss" penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.2;
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0 + (mean_residual * 0.4);
        }
    } else {
        // 5. Fitting Pressure: If this is the only bin that fits the item, make it very attractive.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // 6. Progress-based optimization: In later stages, be more aggressive about filling bins (Best Fit).
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps
    // (e.g., gaps < 10 which cannot fit any incoming items).

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty:
    // If the remaining space is less than the minimum possible item size (10),
    // it is highly likely to become permanent dead space. Heavily penalize this.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
