    if bin_residual == bin_capacity {
        // Penalty scales with how many bins are already open to prevent fragmentation.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward using existing bins, but apply a slight penalty if this bin 
        // ends up significantly below the mean residual of others (to keep bins balanced).
        if (post_residual as f64) < mean_residual {
            score += (mean_residual - post_residual as f64) * 0.2;
        }
    }

    // 4. Critical Threshold Protection:
    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
