        // so we increase the cost of opening a new bin late in the stream.
        score += 40.0 + (progress * 60.0);
    } else {
        // If it's an existing bin, favor bins that are already "fuller" (lower mean_residual)
        // to consolidate remaining space.
        score -= (mean_residual - post) * 0.5;
