    let mut score = post_res;

    // Penalty for creating "slivers" (very small residuals that are hard to fill)
    // We penalize residuals in the (0, 10) range heavily, as they are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size exists, penalize bins that cannot accommodate it
    // if they were the best candidates otherwise.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
