    }

    // Dynamic thresholding: as we near the end of the stream, prioritize closing bins
    // over keeping many bins open with large residuals.
    let closure_pressure = progress * mean_residual;
    score += closure_pressure;

    // Discourage opening a new bin unless the existing fit is extremely poor
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already high (wasting space)
        // or if we are forced to (fitting_bins_count is low).
        score += 40.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that have high occupancy to keep them packed
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Non-linear coupling: penalize having too many open bins as the stream progresses
    score += (open_bins_count as f64).powf(1.2) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #531: Harmonic Residual Optimization
    // Objective: Minimize wasted space while reserving larger gaps for future items.

    let mut score = post_residual as f64;

