    }

    // 5. New Bin Discouragement: Penalize opening a new bin unless the current residual
    // is significantly better than the mean of existing bins.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 15.0; // Base cost to open a new bin
            if post_residual as f64 > mean_residual {
                score += 20.0; // Penalty if the new bin is worse than average
            }
