    } else {
        0.0
    };

    // Integrate lookahead: if the next item fits in the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    let lookahead_bonus = if next_item_size > 0 && (next_item_size as f64) <= post {
        -25.0 * (1.0 + progress)
    } else {
