    };

    // Dynamic thresholding: as the stream progresses, we become more conservative
    // about opening new bins. We penalize the "New Bin" candidate (bin_residual == bin_capacity).
    let new_bin_penalty = if bin_residual == bin_capacity {
        40.0 + (progress * 30.0)
    } else {
        0.0
    };

    // Couple the bin's current state with the global mean to avoid bin fragmentation.
    // If the bin's post-residual is significantly worse than the current mean, penalize.
    let fragmentation_penalty = if post > mean_residual {
        (post - mean_residual) * 0.5
    } else {
