    // 2. Lookahead Synergy: If the post_residual can perfectly or nearly accommodate 
    // the next item, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 1.5;
        } else {
            // Penalize creating a "useless" gap that is too small for the next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 3. New Bin Threshold: If this is an empty bin, calculate a threshold based on
    // current bin utilization. Opening a new bin is only desirable if the average
    // residual is already quite low (suggesting we are filling bins effectively).
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 4. Density Balancing: If we have many open bins, penalize opening new ones 
    // aggressively by adding a factor proportional to the number of open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Lookahead logic: if next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        let potential_after_next = post_residual as i32 - next_item_size as i32;
        if potential_after_next < 0 {
            // Penalize leaving a bin in a state that cannot fit the next item
            score += 15.0;
        } else {
            // Reward keeping space for the next item
            score -= 10.0;
