    // Global state awareness: if many bins are open, try to pack tighter
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 0.5;
    }

    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Favor bins that stay near the global mean residual to keep packing uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit), 
    // but we apply non-linear penalties to prevent fragmentation.

    // 1. Base Score: Reward smaller post-residuals quadratically to favor tight packing.
    let mut score = post * post;

    // 2. Penalty for creating "dead zones": If post_residual is small but > 0, 
    // it often prevents larger future items from fitting. We penalize residuals 
    // in the [1, 15] range specifically.
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post) * 10.0;
    }

    // 3. Lookahead integration: If the next item is large and cannot fit 
    // into the current post_residual, apply a penalty proportional to the 
    // mismatch to encourage keeping space for the next item.
    if next_item_size > post_residual && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 5.0;
    }

    // 4. Stream Progression: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to minimize total count.
    // We reduce the penalty for tight/fragmented fits as progress increases.
    score *= (1.0 - (0.5 * progress));

    // 5. New Bin Logic: If this is a new bin (bin_residual == bin_capacity), 
    // apply a cost based on the number of open bins to discourage opening new ones 
    // unless necessary.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 25.0) + (100.0 * (1.0 - progress));
    }

    // 6. Final adjustment: Reward bins that are closer to the mean residual 
    // to keep the distribution of empty space uniform across bins.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strategy: Minimize "wasted" space while favoring "tight" fits.
    // If post_residual is 0, this is a perfect fit.
    if post_residual == 0 {
