    // Discourage opening new bins unless necessary (fitting_bins_count == 0 implies new bin).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 400.0;
        } else {
            score -= 50.0;
        }
    }

    // Progress-based scaling: as the stream nears the end, become more aggressive about
    // using open bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 10.0;
    }

