    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already open,
    // but allow it if the current fit is extremely poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin if we have many bins open already.
        score += (open_bins_count as f64) * 5.0;
