    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it 
    // to avoid forcing an unnecessary new bin opening.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the post_residual is exactly 0, it's a perfect fit.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
