        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Best-Fit logic: Prefer bins that are tightest (smallest post_residual).
    // The base score already favors low post_residual.

    // 3. Lookahead optimization: If the next item fits in the current post_residual, 
    // reward this bin to keep the current bin "packed" with a sequence.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Open bin pressure: Penalize opening a new bin if we have existing capacity.
    // If this is a new bin (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Global state normalization: If the mean residual is high, we are under-filling.
    // Discourage opening new bins if the average bin is already quite empty.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += mean_residual;
    }

    // 6. Last chance heuristic: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: penalize large post_residuals (wasted space).
    // If post_residual is 0, this is an exact fit, which is ideal.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead matching: If the next item fits into the post_residual,
    // we strongly favor this bin to keep the bin tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Penalty for opening a new bin:
    // If the bin is new, add a significant penalty unless it's the only option.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 4. Global balance: If this bin's residual is much higher than the mean, 
    // it is a "loose" bin. We penalize adding to loose bins to keep them available 
    // for larger items, favoring "tighter" bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // 5. Critical Thresholding: If this is the only bin that fits the current item, 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progress Adaptation: As the stream progresses, become more aggressive 
    // about filling bins (less tolerance for high post_residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size fits in current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // 3. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 150.0 + (100.0 * (1.0 - progress));
        } else {
            // If no other options, normalize score to encourage opening
            score = 50.0;
        }
    }

    // 4. Global state coupling: Encourage filling bins that are already "tight"
    // relative to the mean to avoid fragmenting the bin space
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Critical threshold: Avoid leaving small slivers (e.g., < 10) that are 
    // unlikely to be filled later in the stream
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - progress);
    }

    // 6. Dynamic time horizon: As the stream nears the end, increase the 
    // pressure to consolidate by rewarding bins that approach zero residual
    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too empty to be useful later in the stream.
    // As progress increases, we become more aggressive about filling bins (Best Fit).
    // If post_residual is small, we reward it, but we penalize it if we could have 
    // used a bin that was already nearly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (1.0 - fill_ratio) * 10.0 * (1.0 - progress);

    // Lookahead logic: if the next item is large, we want to prioritize keeping
    // large residuals available.
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual < next_item_size {
            (next_item_size - post_residual) as f64 * 0.5
        } else {
            0.0
        };
        score += next_fit_penalty * (1.0 - progress);
    }

    // Discourage opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are very poorly utilized.
        // We add a threshold barrier that decreases as we run out of items.
        let new_bin_threshold = 25.0 + (progress * 25.0);
        score += new_bin_threshold;
    } else {
        // If it's an existing bin, penalize if it's the only one that fits, 
        // to encourage keeping it for a potentially better future fit.
        if fitting_bins_count == 1 {
            score -= 5.0 * (1.0 - progress);
        }
    }

    // Non-linear coupling: penalize high residual variance if we are near the end.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit typical items (10-30 range)
    // If post_residual is small but > 0, it's often a "fragmentation" trap.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_residual as f64 / 20.0));
    }

    // 2. Harmonic Class Logic: Favor residuals that align with common item sizes.
    // If the next item is large, we want a larger post_residual to accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Severe penalty for stranding a large item
            score += 120.0;
        } else {
            // Reward residuals that are "tight" but sufficient for the next item
            let buffer = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 / (1.0 + buffer));
        }
    }

    // 3. Pressure management: If this is the only bin that fits the item, 
    // prioritize it heavily unless it's a very poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. Global state awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 50.0; // Discourage new bins late in the game
    }

    // 5. Harmonic Penalty: Penalize residuals that are not multiples of common item sizes (e.g., 25, 33, 50)
    // This reduces fragmentation by encouraging "perfect" fits.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (residual gaps too small to fit typical future items)
    // Small gaps (1-9) are highly undesirable as they are unusable for most inputs.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
