    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // We favor bins where post_residual is small (near 0) to maximize packing density.

    // 2. Lookahead Coupling: If next_item_size fits in current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Harmonic refinement: if post_residual is a near-perfect fit for the next item, reward more.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Harmonic Class Logic: Penalize "Fragmented" bins (post_residual < 10)
    // Small residuals are often "dead space" that cannot fit future items.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // 4. Scarcity Logic: If this is the only bin that fits, prioritize it heavily to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive at closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. New Bin Thresholding:
    // If evaluating an empty bin (bin_residual == bin_capacity), set a threshold.
    // Opening a new bin is penalized unless the open bins are highly inefficient.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0; // Moderate penalty to force reuse unless mean residual is high.
        } else {
            score += 45.0; // High penalty to prevent opening new bins prematurely.
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the remaining space is too small to fit typical future items,
    // penalize heavily to push for tighter packing. We consider gaps < 10 as "wasted".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bins Pressure: Penalize opening a new bin if we have many bins already open.
    // This encourages consolidating items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 3. Lookahead Synergy: If the next item can fit in the current post_residual,
    // reward this bin highly to keep the bin useful for the immediate future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Scarcity Logic: If this is the only bin that can fit the current item, 
    // prioritize it to avoid forced new-bin allocations.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Global Mean Alignment: Avoid bins that deviate significantly from the mean
    // residual to keep the distribution of remaining space uniform across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize leaving a tiny sliver (dead space).
    // If post_residual is small but > 0, it's often better to open a new bin if the item is large.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits perfectly into this bin's post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 0.5;
    }

    // 3. New Bin Thresholding: If we are forced to open a new bin (fitting_bins_count == 0), 
    // prioritize keeping the mean_residual of existing bins healthy.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual < 25.0 {
            score += 50.0; // Discourage opening new bins if existing ones are already tight.
        }
    } else {
        // 4. Density Balancing: Favor bins that stay near the global mean_residual.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.2;
    }

    // 5. Progression Scaling: As we approach the end of the stream, prioritize closing bins (lower residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.3);

    // 6. Last Chance Logic: If this is the only bin that can fit, take it regardless of fit quality.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead zones": residuals smaller than the smallest likely item
    // but larger than zero are generally bad. We penalize small residuals more heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that maintain the ability to fit the next item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // Global state awareness: if we have too many bins open, penalize opening new ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // Heuristic pressure: if this is the only bin that fits, we are forced,
    // so we reduce the penalty to prevent artificial new-bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Balance the mean residual: if this bin's post_residual is much worse than the mean,
    // we penalize it to keep open bins packed similarly.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // We aim to minimize the score.
    // 1. Base cost is the remaining space (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize new bin creation heavily, but allow it to scale down as we approach 
    // the end of the stream to avoid forcing bad fits late in the process.
    if is_new_bin {
        score += 15.0 * (1.0 - progress);

        // If we have many open bins, penalize opening a new one more aggressively.
        score += (open_bins_count as f64) * 2.5;
    }

    // 3. Lookahead coupling: If next_item_size is large, favor bins that leave 
    // enough room for it (post_residual >= next_item_size).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that would "starve" the next item.
            score += 20.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Entropy control: If the bin is nearly full (post_residual < 10), 
    // reward it to "close out" bins, unless it's a new bin.
    if !is_new_bin && post_residual < 10 {
        score -= 12.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 5. Global state normalization:
    // If mean_residual is high, we are currently being wasteful; 
    // force stricter adherence to Best Fit (lower post_residual).
    score += (mean_residual / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "fragmented" space (dead space < 10, the minimum item size)
    // We heavily penalize residuals that are too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If the next item is large, avoid small post_residuals.
    // If post_residual is smaller than the next item, we create a dead space penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. Bin consolidation: Encourage filling bins that are already "near" their mean capacity.
    // If we have many open bins, we want to prioritize closing them or filling them tightly.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Scarcity heuristic: If this is the only bin that fits, we are forced, but we
    // penalize opening a new bin if the current fit is poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: proportional to how well we are doing overall.
        // If we have few open bins, opening a new one is less costly.
        score += (open_bins_count as f64 * 5.0) + (100.0 / (fitting_bins_count + 1) as f64);

        // If the item is large (e.g., > 50), opening a new bin is better than a bad fit.
        if item_size > 50 {
            score -= 20.0;
        }
    }

    // 5. Progress scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "dead zones" (residual < 10) 
    // and managing the count of open bins to prevent fragmentation.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is small but not zero, 
    // it is likely to be unusable for future items (which are >= 10).
    // Heavily penalize residuals in the (0, 10) range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // 3. Open bins pressure: If this is an empty bin, penalize it based on how many
    // bins are already open to discourage opening new bins unnecessarily.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have very few open bins, opening a new one is less costly.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    }

    // 4. Fitting constraints: If this is the last chance for this item to fit 
    // in an existing bin, reduce the score to prioritize filling it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global efficiency: Favor bins that stay closer to the mean residual 
    // of the existing pool to maintain uniform packing density.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless necessary (fitting_bins_count == 0)
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0;
    }

    // 2. Best-Fit logic: prioritize bins where post_residual is small
    // We favor bins that leave little room (Best-Fit principle)
    score += post_residual as f64 * 0.5;

    // 3. Lookahead matching: If post_residual is close to next_item_size, reward this bin
    // This creates "perfect fit" chains that minimize future fragmentation
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 1.5;
    }

    // 4. Mean-Residual alignment: discourage creating bins that deviate significantly from average
    // This promotes uniform filling patterns across the bin set
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling: tighten constraints towards the end of the stream
    let progress = step_index as f64 / total_items as f64;
    if post_residual < 10 && progress > 0.8 {
        score -= 50.0; // Aggressively finish off bins at the end of the stream
    }

    // 6. Penalty for creating tiny, unusable gaps that cannot fit even the smallest items (10)
    if post_residual < 10 && post_residual > 0 {
