    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual while penalizing fragmenting bins that could hold future items.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: Preference for tightest fit (Best-Fit approach)
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin prematurely
    if is_new_bin {
        // If there are other bins that can fit the item, penalize opening a new one heavily,
        // but scale the penalty down as we approach the end of the stream (to avoid bin bloat).
        score += (fitting_bins_count as f64 * 40.0) * (1.0 - progress * 0.5);
    } else {
        // 3. Lookahead Logic: If this bin fits the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // 4. Global State: Penalize creating "dead zones" (small residuals) 
        // that are unlikely to fit future items.
        if post_residual > 0 && post_residual < 15 {
            score += 30.0;
        }

        // 5. Dynamic balancing: If we have many open bins, penalize filling bins 
        // that have a high residual, encouraging consolidation.
        if open_bins_count > 5 {
            score += (bin_residual as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // 6. Final normalization: Favor using bins that are closer to the mean residual
    // of all open bins to maintain a uniform "fill" across the set.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable slivers (dead space 1-9)
    let sliver_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (10.0 - post_residual as f64)
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item
    let fit_reward = -1.5 * (bin_capacity as f64 - post);

    // Lookahead: penalize if this choice leaves a bin that cannot fit the next item
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Global state optimization: balance the residual across bins
    let balance_penalty = 0.5 * (post - mean_residual).abs();

    // If bin is empty (new bin candidate), apply progress-based cost scaling
    // Opening a new bin becomes increasingly expensive as we approach the end of the stream
    let new_bin_cost = if bin_residual == bin_capacity {
        25.0 + (35.0 * progress)
    } else {
        0.0
    };

    // Interaction term: favor filling bins that are already "half-full" as progress increases
    let usage_factor = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    let efficiency_bonus = -5.0 * usage_factor * progress;

    let score = post + sliver_penalty + fit_reward + lookahead_penalty + balance_penalty + new_bin_cost + efficiency_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

