    // 2. Harmonic Penalty: If post_residual is small but not zero, it creates "dead space"
    //    that cannot fit the smallest items (typically 10-20).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead synergy: If next_item_size is known, favor bins that can fit it.
    // If post_residual is smaller than next_item_size, we effectively force a new bin later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // 4. New bin management: discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of current bins is very high (already inefficient).
        if open_bins_count > 0 && mean_residual < 25.0 {
            score += 100.0;
        } else {
            score += 10.0;
        }
    }

    // 5. Fitting scarcity: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Distributional adaptation: As we progress, tighten constraints on residuals.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
