        } else {
            // If it's the only option, normalize the cost.
            score += 10.0;
        }
    }

    // 3. Lookahead optimization: If a future item could fit in the current post_residual,
    // reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
