            score += 15.0;
        }
    }

    // 3. Pressure management:
    // If this is the only bin that can fit the current item, prioritize it to avoid 
    // unnecessary new bin creation (unless the fit is extremely poor).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 4. Global distribution alignment:
    // Prefer bins that stay close to the current mean_residual to keep load balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. New bin penalty/threshold:
