}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We add a penalty for creating a "fragment" (small, unusable residual)
    // Fragment penalty is higher when the stream is nearly finished to avoid waste.
    let fragment_penalty = if post > 0.0 && post < 10.0 {
        10.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead interaction: If next_item can fit in the post_residual, reward this placement.
    // We use a non-linear scaling to favor bins that leave enough space for the next item.
    let lookahead_reward = if next_item_size > 0 && (post_residual >= next_item_size) {
        -25.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Penalty for opening a new bin:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We penalize opening new bins heavily early on, but less so as the stream ends.
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options
            150.0 * (1.0 - progress)
        } else {
            // No options, forced to open a new bin
            0.0
        }
    } else {
        0.0
    };

    // Interaction between current bin state and global mean:
    // Avoid creating bins that are significantly worse than the current average.
    let efficiency_bias = (post - mean_residual).max(0.0) * progress;

    post + fragment_penalty + lookahead_reward + new_bin_penalty + efficiency_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual
    // 2. Penalty for creating "dead space" (small residuals that cannot fit common items)
    // We penalize residuals that are smaller than the smallest likely future items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 3. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Reward tighter packing for the second item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 4. Harmonic/Modulo pressure: Avoid bins that leave residuals that are "awkward" 
    // (e.g., leaving 20-30 space is often worse than leaving <10 or >40)
    if post_residual >= 20 && post_residual <= 35 {
        score += 15.0;
    }

    // 5. Global state normalization: If we have many open bins, prioritize closing them (lower residual)
    // If we have few open bins, we can afford to be more selective to save space for future items
    if open_bins_count > 5 {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 6. New bin candidate handling:
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary.
    if bin_residual == bin_capacity {
        score = 60.0; // Base cost to open a new bin
        // If fitting_bins_count is 0, we MUST open a new bin.
        if fitting_bins_count == 0 {
            score = -100.0; 
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "unusable" gaps (1..9) 
    // and managing the growth of open_bins_count.

    let mut score = post_residual as f64;

    // Penalty for creating "Dead Zones": 
    // Residuals between 1 and 9 are often impossible to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Pressure factor: If this is an existing bin (not a new empty one),
    // reward it slightly to keep open_bins_count low.
    if bin_residual < bin_capacity {
        score -= 5.0;
    }

    // If this is the only bin that fits the current item, 
    // heavily reward it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Dynamic scaling: As the stream nears the end, become more conservative
    // about opening new bins by penalizing the "New Bin" candidate.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // However, we apply a non-linear weight to differentiate between "tight" and "too tight".
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Matching: Reward bins where the post_residual can accommodate the next item.
    // This is the core of the 2-step lookahead strategy.
    if next_item_size > 0 {
