    // 4. New Bin Thresholding: Prevent opening a new bin unless the fit is truly abysmal.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no good options or we are forced to.
        // Penalty scales with how many existing bins can already fit the item.
        score += 35.0 + (fitting_bins_count as f64 * 15.0);

        // As the stream progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Urgency: If this is the last chance to fit the item (fitting_bins_count == 1),
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
