        // Reward filling existing bins to reduce open_bins_count
        score -= (open_bins_count as f64).sqrt() * 5.0;
    }

    // Interaction with mean_residual:
    // If this bin's post_residual is significantly better than the global mean, reward it.
    let residual_diff = mean_residual - post;
    score -= residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
