    //    is extremely ill-suited for the current item or future items.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider a new bin if the current open bins are "full enough" 
        // that placing this item would leave them with unusable fragments.
        score += 45.0; 
