        score -= (fitting_bins_count as f64).ln() * 5.0;
    }

    // Discourage leaving space below a threshold that is unlikely to be filled later
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

