        0.0
    };

    // Calculate base score: favor smaller post_residual (Best Fit)
    // Add non-linear penalty for fragmentation (post_residual < next_item_size)
    let fragmentation_penalty = if !is_new_bin && next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Coupling: If fitting_bins_count is low, prioritize filling the bin to consolidate
    let urgency_factor = if fitting_bins_count == 1 && !is_new_bin {
        -20.0 
    } else {
        0.0
    };

    // Smooth interaction: post_residual vs mean_residual
    // Prefer bins that stay close to the running average residual to maintain uniformity
    let deviation_penalty = (post_residual as f64 - mean_residual).abs() * 0.5;

    let mut score = post_residual as f64 
        + new_bin_penalty 
        + fragmentation_penalty 
        + urgency_factor 
        + deviation_penalty;

    // Ensure the new bin candidate is only chosen if it's the only option or very efficient
    if is_new_bin && fitting_bins_count > 0 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic 721: Harmonic-Residual Balancing
    // Strategy: Penalize small fragments that cannot accommodate future items, 
    // while prioritizing Best-Fit with a lookahead incentive for future-item compatibility.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones" (fragments < 10 which cannot fit any item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the post_residual, 
    // reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Harmonic class alignment: Prefer residuals that are multiples of common item sizes (20, 25, 33)
    // to keep the bin flexible for larger items.
    if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 4. New bin management: If this is a new bin (residual == capacity), 
    // only choose it if the fitting_bins_count is low or if current open bins are high-fragmentation.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 5.0; // Necessary to open
        } else {
            // Heavily penalize opening a new bin if an existing one can hold the item
            score += 100.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Global state normalization: If the bin is becoming too empty relative to the mean, 
    // discourage adding to it to preserve "tight" packing.
    if (post_residual as f64) > mean_residual && open_bins_count > 1 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
