    // 2. Lookahead Integration: If the next item can fit in the current post_residual, 
    // heavily reward this bin to keep items together.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Avoidance: If we are creating a "dead space" (e.g., residual < 10),
    // penalize this bin heavily as it's unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one 
    // or using a bin that increases the count of fragmented bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless the fitting options are terrible.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Dynamic Time Horizon: As we reach the end of the stream, prioritize closing 
    // the current bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Scarcity Adjustment: If this is the only bin that can fit the item, 
    // make it highly attractive to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 7. Mean Residual Balancing: If the current bin's residual is significantly 
    // higher than the mean, penalize it to encourage packing items into tighter bins.
    if bin_residual < bin_capacity && (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too empty early in the stream, 
    // but reward using "tight" bins as the stream progresses to consolidate space.
    let tightness_factor = (bin_capacity as f64 - post) / bin_capacity as f64;
    score -= (tightness_factor * progress) * 20.0;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that scales with the availability of existing fitting bins.
    if bin_residual == bin_capacity {
        score += 45.0 + (fitting_bins_count as f64 * 15.0);
    }

    // Lookahead influence: If the next item is large, penalize bins that leave 
    // residual space just slightly smaller than the next item (creating dead space).
    if next_item_size > 0 {
        let diff = post - next_item_size as f64;
        if diff >= 0.0 && diff < 10.0 {
            // This is a "bad" fit for the next item, penalize proportionally.
            score += (10.0 - diff) * 5.0;
        }
    }

    // Favor bins that align with the current mean residual to keep bin states uniform.
    let residual_deviation = (post - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a "sliver" (fragmented space that rarely fits future items)
    // Small residuals (1-9) are usually dead space given the item distribution (10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Best-Fit logic: prioritize bins where the item fits perfectly or fills most of the space
    // We heavily reward post_residual == 0 (perfect fit)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead logic: If the next item can fit in the post_residual, prioritize this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Adaptive thresholding: If we are near the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;

    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Penalize opening new bins unless we have many open bins that are nearly full
        // or if we are early in the stream.
        score += 15.0 + (open_bins_count as f64 * 2.0);

        // If it's the only option, reduce the penalty
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Prefer bins that are closer to the mean residual to keep bins balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Harmonic class logic: penalize odd-sized remainders that don't divide common item sizes
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
