pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals that are too small to fit typical future items (<10)
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.5);
    }

    // Harmonic Fit: Encourage post_residuals that are multiples of larger items to minimize fragmentation.
    // We penalize residuals that don't align well with the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // Strong incentive to keep space for the next item
        } else {
            score += 15.0; // Penalty for stranding the next item
        }
    }

    // Harmonic Class Logic: Prefer filling bins to specific thresholds (e.g., 20, 33, 50).
    // If the post_residual is near a harmonic fraction of capacity, reward it.
    let harmonic_penalty = ((post_residual as f64 % 25.0) - 12.5).abs();
    score += harmonic_penalty * 0.5;

    // Global context: If we are late in the stream, prioritize compacting open bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // Handle New Bin Candidate:
    // If bin_residual == bin_capacity, this is a new bin. 
    // We only open a new bin if the current "best" fit is extremely poor (post_residual is very large).
    if bin_residual == bin_capacity {
        // Only consider a new bin if the existing fits are poor (e.g., leaving > 40 space).
        // Otherwise, make the new bin score high (unattractive).
        score = 40.0 + (open_bins_count as f64 * 2.0);
    }

    // Fitting Bins Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "orphaned" gaps
    // that are too small to fit typical future items (10..80).
    // Penalize opening new bins unless the current bin fit is extremely poor.

    let mut score = post_residual as f64;

