        // If we are forced to open a new bin, ensure it's not worse than a 
        // bad fit in an existing bin.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // 4. Mean Residual Balancing: If the bin is emptier than the average, 
    // it's a better candidate for placing items to keep the bin count low.
    if post_residual < (mean_residual as u32) {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // 5. Final normalization: Favor bins that are tighter fits (lower post_residual).
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
