            score = 40.0;
        }
    }

    // 5. Mean Residual Balancing:
    // Favor bins that align with the current average density to keep bins uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Progress Scaling:
    // As the stream nears the end, prioritize tightly packing remaining items.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
