pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses
    // to discourage starting new bins late in the lifecycle.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (progress * 50.0));

    // Best Fit Decreasing (BFD) logic: prioritize bins where the post_residual is smallest.
    // We add a non-linear interaction: as the stream progresses, we become more aggressive 
    // about filling bins tightly to avoid fragmentation (the 'tightness_bonus').
    let tightness_bonus = post.powf(1.5) * (1.0 + progress);

    // Lookahead coupling: if the next item is large, favor bins with more space (higher post_residual).
    // If the next item is small, favor bins with less space (lower post_residual).
    let lookahead_mod = if next_item_size > 0 {
        let n = next_item_size as f64;
        let delta = (n - post).abs();
        delta * 0.5 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalize the creation of "dead zones" (residuals < 10) that are unlikely to fit future items,
    // unless it is the very end of the stream.
    let dead_zone_penalty = if post < 10.0 && post > 0.0 && progress < 0.9 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Combine factors:
    // Lower score is better.
    let mut score = tightness_bonus + new_bin_penalty + lookahead_mod + dead_zone_penalty;

    // If only one bin can fit the item, we are forced to be less picky, 
    // but if it's a new bin, we keep the penalty high.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
