    // 2. Lookahead Integration: If next_item_size is large, favor larger post_residuals 
    // to accommodate it (Best-Fit vs Next-Fit balance).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 30.0 * (1.0 - progress);
        } else {
            score -= 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // 3. Global Bin Utilization: If we have many open bins, prioritize closing them 
    // (Best-Fit). If we have few, be more conservative with space.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 10.0; // Encourage filling existing bins that are "last chances"
    }

    // 4. New Bin Logic: Discourage opening a new bin unless the existing fit is 
    // significantly worse than a fresh start.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the current mean residual is very tight 
            // or if we are nearing the end of the stream.
            score = 40.0 + (mean_residual * 0.5) + (progress * 20.0);
        }
    } else {
        // Dynamic scaling based on density of open bins
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

