    // We want to minimize wasted space, so smaller post_residual is generally better.
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that cannot fit common items).
    // If post_residual is between 1 and 9, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // we reward this placement significantly to promote packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
