pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #846: Harmonic-Residual-Pressure (HRP)
    // Minimizes post_residual while applying non-linear penalties for creating "orphan" space
    // that cannot accommodate typical future items (modulo 25-33 range).

    let mut score = post_residual as f64;

    // 1. Best-Fit Bias: Heavily reward residuals that approach zero (Perfect fit)
    // The exponential dampening forces the heuristic to prioritize tightest bins.
    score -= 100.0 * (1.0 / (1.0 + post_residual as f64));

    // 2. Harmonic Class Penalty: 
    // Penalize residuals that are "useless" (too small for most items, e.g., < 10)
    // but not zero. These create fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
