    // 3. Lookahead Synergy:
    // If next_item_size fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 4. Entropy Control:
    // Avoid opening new bins unless necessary. If fitting_bins_count is high,
    // penalize the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + (fitting_bins_count as f64 * 10.0);
    }

    // 5. Mean Residual Balancing:
    // Penalize bins that deviate significantly from the current average utilization
    // to keep the bin distribution uniform (avoids "clustering" items in one bin).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 6. Progress Scaling:
    // As we approach the end of the stream (step_index), become more aggressive
    // about closing bins (minimizing total bins).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

