    score += residual_diff * 0.1;

    // 6. Progress factor: Be more aggressive in packing as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor bins that leave the least space (Standard Best-Fit)
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If post_residual perfectly accommodates next_item_size, heavily reward it.
    // We subtract score to make this bin the preferred choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 2.0;
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current mean_residual is very low.
    // If we have few fitting bins, we are desperate; if we have many, we can be picky.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0; // Essential to open the first bin
        } else {
            // Penalize opening a new bin if existing bins have plenty of space on average
            score += mean_residual * 0.8;
            // Penalize opening a new bin if we have other choices
            if fitting_bins_count > 0 {
                score += 40.0;
            }
        }
    }

    // 4. Tightness bias: If post_residual is extremely small (0-5), it's a high-quality bin.
    if post_residual < 5 {
        score -= 20.0;
    }

    // 5. Progression damping: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual space (Best Fit strategy).
    // Lower post-residual is generally better (tighter packing).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor or if we are forced.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin, neutralize penalty.
            score = 0.0;
        } else {
            // Heavily penalize opening a new bin if existing ones can fit it.
            // Scale penalty by how well the item would have fit in the "best" existing bin.
            score = 50.0 + (mean_residual * 0.5);
        }
    } else {
        // Lookahead heuristic: If the next item is large, avoid leaving a tiny residual 
        // that cannot accommodate future items (dead space penalty).
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                // We created a "fragmented" bin that likely can't fit the next item.
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }

        // Global state awareness:
        // If we have many open bins, prioritize finishing the ones with the least residual.
        if open_bins_count > 5 {
            score += (bin_residual as f64 - mean_residual).abs() * 0.2;
        }

        // Dynamic time horizon:
        // As we reach the end of the stream, prioritize closing bins over opening new ones.
        if progress > 0.8 {
            score -= (post_residual as f64) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize larger post_residuals to encourage tight packing
    let mut score = post;

    // Non-linear coupling: Exponential penalty for leaving small gaps that are hard to fill.
    // We define a 'dead-zone' threshold near 10-20 units.
    if post < 20.0 && post > 0.0 {
        score += (20.0 - post).powf(1.5);
    }

    // Lookahead logic: if next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            // Reward bins that are perfectly sized for the next incoming item
            score -= (post - next_item_size as f64).abs().powf(0.5) * 5.0;
        } else {
            // Penalize bins that will be too small for the next item
            score += 15.0 * (1.0 - progress);
        }
