    // Dynamic thresholding: as we reach the end of the stream, 
    // prioritize closing open bins over opening new ones.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream
        // to force utilization of existing fragmented space.
        score += 40.0 * (1.0 + progress);

        // If we have many open bins, penalize opening another one heavily
        score += open_bins_count as f64 * 2.0;
    }

    // Interaction with mean_residual:
    // If our current bin's post_residual is significantly worse than the average, penalize it.
    if post > mean_residual {
        score += (post - mean_residual).powf(1.2);
    }

    // Final constraint: If this is the last chance for this item (only 1 bin fits), 
    // significantly reduce its score to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Penalize large post_residuals (wasted space)
    // The lower the post_residual, the better the fit.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: If post_residual is small, it's often better to save it for 
    // medium items. If post_residual is a multiple of common item sizes, reward it.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0; // Penalty for creating "slivers" that are hard to fill
    }

    // 3. Lookahead integration: Try to fit next_item_size into the post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0; // Strong reward if current placement allows next item to fit
        } else {
            score += 10.0; // Penalty if next item is blocked by this placement
        }
    }

    // 4. Thresholding: Avoid opening a new bin unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavily penalize opening a new bin if an existing one fits
        } else {
            score -= 50.0; // Otherwise, facilitate opening a new bin
        }
    }

    // 5. Density heuristic: If the bin is already quite full, prioritize finishing it
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 20.0;

    // 6. Global state adjustment: If many bins are open, favor filling existing ones
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

