    // 4. Global balance:
    // If this is the only bin that fits the item, avoid opening a new one unless it's a perfect fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. If considering a new bin (bin_residual == bin_capacity):
    // Only pick a new bin if the current open bins are all "cluttered" (high mean_residual relative to item_size).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > (item_size as f64 * 0.8) {
            score += 10.0;
        } else {
            // Otherwise, heavily penalize opening new bins
            score += 60.0;
        }
