        }

        // Global state awareness:
        // If the mean residual of our bins is high, we are being too wasteful.
        // Force tighter packing by penalizing bins that increase the mean residual.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }

        // If this is the last bin that can fit the current item, 
