}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small, unusable gaps.
    // If post_residual is < 10, it is likely "dead space" because min item size is 1.
    // We prioritize bins that result in 0 residual (Perfect Fit) or larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Open Bin Pressure: Penalize opening new bins if there are existing options.
    // If this is a new bin, apply a penalty based on how many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If the next item can fit in this bin's post_residual,
    // reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
