    }

    // 4. Fitting Scarcity: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual
    // to keep the bins filled at a similar rate.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
