pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual).
    // The base score starts at post_residual.

    // 2. Penalty for creating "dead zones" (unusable space < 10).
    // If post_residual is small but > 0, it's often better to leave it larger if possible,
    // or perfectly empty (0).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: If a bin fits the current item AND the next item, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Harmonic/Fractional balancing:
    // Prefer bins whose residuals align with common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 5. New Bin thresholding:
    // If we are about to open a new bin (bin_residual == bin_capacity), 
    // only do so if the current fitting options are poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few options.
        score += 40.0;

        // If we have many open bins already, penalize opening more.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If fitting_bins_count is 1, this is the only bin that can take this item.
        // We should reward taking it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 6. Progress-based scaling:
    // As we reach the end of the stream, prioritize closing bins (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 / 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict dead space avoidance: 
    // If the post_residual is smaller than the smallest possible item size (10),
    // it creates a "fragment" that is likely unusable. Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization:
    // If we know the next item, penalize bins that leave a post_residual 
    // that cannot accommodate the next_item_size, unless it's a perfect fit (0).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // 3. Open bins pressure:
    // When fitting_bins_count is 1, this bin is the only current option.
    // We should favor this over opening a new bin (where bin_residual == bin_capacity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. Global bin count regulation:
    // As the stream progresses, penalize opening new bins (bin_residual == bin_capacity)
    // proportional to the number of already open bins to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we are late in the stream, discourage opening new bins unless necessary
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 5. Mean residual balancing:
    // Penalize bins that deviate from the mean residual to keep bin levels uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
