    // Penalize opening new bins if there are still plenty of fitting bins available.
    if is_new_bin && fitting_bins_count > 0 {
        score += (fitting_bins_count as f64 * 20.0) * (1.0 - progress * 0.5);
    }

    // Dampen score based on mean_residual to prevent over-packing early bins
    // at the cost of forcing too many new bins later.
    score += (mean_residual - post_res).abs() * 0.1;

    score
}

