    // 5. New Bin Control: Only open a new bin if the current fit is catastrophic (high post_residual)
    // or if the stream is in the early stages where high variance is tolerable.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Always open the first bin
        } else {
            // New bin is only attractive if all existing bins result in very poor fit
            score = 40.0 + (progress * 20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We penalize small residuals (dead space) non-linearly
    let mut score = post * post * 0.01;

    // Favor bins that align with the next item size (lookahead)
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * (1.0 - progress);
    }

    // Dynamic penalty for opening new bins
    if bin_residual == bin_capacity {
        // As the stream progresses, increase the cost of opening new bins
        // to encourage packing into existing under-utilized bins.
        score += 25.0 + (progress * 50.0);
    }

    // Encourage filling bins that are already "emptier" than the average
    // to keep the bin distribution uniform.
    if bin_residual < bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.5;
    }

    // Penalize bins that leave very little space (e.g., 1-5) as these are often "dead" 
    // unless the item is small.
    if post_residual > 0 && post_residual < 6 {
        score += 15.0 * (1.0 - progress);
    }

    // If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Favor small residuals (Best Fit)
    // We penalize large post_residuals to keep bins tightly packed.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin to prevent fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Avoidance: If this bin is the last one that can fit the item,
    // be careful not to create a "dead" gap (e.g., 1-9 remaining).
    if fitting_bins_count == 1 && post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Distribution Balancing: If the current post_residual creates a space that is 
    // smaller than the average residual, it is likely to become unusable.
    if (post_residual as f64) < mean_residual {
        score += 10.0;
    }

    // 5. New Bin Thresholding: 
    // Penalize opening a new bin unless the current open bins are already very full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // If we have many bins with large space, don't open a new one.
            score += 100.0;
        } else {
            // Otherwise, keep the cost of a new bin neutral to allow it if fits are poor.
            score += 40.0;
        }
    }

    // 6. Harmonic Class Logic:
    // If the residual is a small multiple of the item size, it's a good fit.
    if item_size > 0 && post_residual % item_size == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual if it leaves a "sliver" (1-9) 
    // that is too small to fit the smallest expected items (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Fragmentation Penalty: Penalize bins that deviate significantly from the mean 
    // residual of the current set, as tight packing is preferred.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Global Bin Pressure: If this is the only bin that fits the item, 
    // heavily favor it to prevent opening unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // heavily penalize it unless the open bin count is very low, to enforce consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we are late in the stream, be more conservative about opening new bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

