    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // 4. Balance current bin usage against the global mean_residual.
    // If the current bin's post_residual is significantly lower than the average, 
    // it's a good candidate for packing tightly.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progressive scaling: as we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (tight fits).
    let mut score = post_residual as f64;

    // Penalty for leaving "sliver" gaps that are too small to fit typical future items.
    // If the post_residual is small but > 0, it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to consolidate items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state awareness: If we are near the end of the stream, 
    // be more aggressive about filling existing bins to avoid leftover bins.
    if progress > 0.8 {
        score -= (1.0 - progress) * 50.0;
    }

    // Dynamic new-bin constraint:
    // If we have many open bins, penalize opening a new one.
    // If we have very few bins and the fit is poor, consider opening a new one.
    if is_new_bin {
        if fitting_bins_count == 0 {
            // Must open a new bin, neutralize penalty.
            score = 5.0;
        } else {
            // Penalize opening a new bin if other options exist, 
            // scaled by how many bins are already open.
            score = 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Encourage using bins that bring the mean residual closer to the ideal 
        // (which is usually around 10-20% of capacity).
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it's often better to have left a larger gap or filled it perfectly.
    // We penalize values in the [1, 10] range non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res).powi(2) * 2.5;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Progression logic: As we approach the end of the stream, prioritize 
    // tightly packing existing bins over opening new ones.
    if fitting_bins_count > 0 {
        // If this is an existing bin, reduce score to favor it over a new bin.
        if bin_residual < bin_capacity {
            score -= (1.0 - progress) * 20.0;
        }
    } else {
        // If this is a new bin (bin_residual == bin_capacity)
        // Heavily penalize opening a new bin early in the stream.
        score += (1.0 - progress) * 50.0;
    }

    // Influence of open_bins_count: penalize opening too many bins relative to mean_residual
    // to encourage density.
    score += (open_bins_count as f64) * (100.0 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (dead space).
    // If post_residual is small (1-9), it often creates fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64).sqrt();
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // we heavily reward this bin to maximize packing density (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further refine: reward if it leaves very little space after the next item.
        let post_post = post_residual - next_item_size;
        if post_post == 0 {
            score -= 20.0;
        }
    }

    // 3. Modulo Alignment: Favor residuals that align with common item size divisors.
    // This helps maintain "clean" bins for incoming items.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    // 4. Scarcity/Load Balancing: If we are forced to choose, prefer bins that 
    // are already "more full" (lower mean_residual) to keep fresh bins open.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // all other options are extremely poor (i.e., would leave highly fragmented space).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 45.0;

        // If we have very few fitting bins, opening a new one is more attractive 
        // than forcing a bad fit into a nearly full bin.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }

        // As the stream progresses, prioritize closing bins to reduce total count.
        score += (step_index as f64 / total_items as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual while avoiding "dead space" (gaps < 10, as items are >= 10).
    // If a bin is empty (bin_residual == bin_capacity), it is a candidate for opening a new bin.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base cost: The tighter the fit, the better (minimize post_residual).
    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable space (gaps < 10). 
    // Since items are >= 10, any residual < 10 is effectively wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead heuristic: If the next item can fit in the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Pressure management:
    // If we are late in the stream, avoid opening new bins unless necessary (high penalty for new bins).
    // If fitting_bins_count is low, we are running out of options for this specific item.
    if is_new_bin {
        score += 30.0 + (progress * 40.0);
        if fitting_bins_count > 0 {
            score += 100.0; // Heavily discourage new bin if existing ones work
        }
    } else {
        // Reward utilizing existing bins to reduce open_bins_count.
        score -= (open_bins_count as f64) * 0.5;

        // If this bin is the last chance for the current item, bias towards it.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Balance with mean_residual to favor bins that are already "fuller" than the average.
    if (bin_capacity - bin_residual) > (bin_capacity as f64 - mean_residual) as u32 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

