    }

    // 6. Progression Scaling:
    // As we approach the end of the stream, prioritize closing bins (tight fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize Best-Fit space while penalizing "fragmentation" using lookahead and global mean state.
    // We prioritize bins that result in a post_residual that is either 0 (perfect fit) or 
