    // Lookahead logic: If the next item could fit in this bin, prioritize this bin.
    // We reward bins that can accommodate the next item by reducing the score.
    if next_item_size > 0 && post_res >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic adaptation: As the stream progresses, prioritize tighter packing
    // to avoid fragmentation near the end of the stream.
    score += (progress * 20.0) * (post_res / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the stream progresses, allowing new bins only when necessary.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        let new_bin_cost = 45.0 * (1.0 - (progress * 0.5));
        score += new_bin_cost;
    }

    // Penalize bins that deviate significantly from the mean residual of all open bins
    // to keep the packing density uniform across bins.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.2;

    // If this is the last fitting bin, reward it slightly to keep the count of open bins low.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

