        score += 50.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: If the next item is large, penalize small residuals 
    // that won't accommodate it, prioritizing bins that leave room for upcoming items.
    if next_item_size > 0 {
        let fit_margin = post - next_item_size as f64;
        if fit_margin < 0.0 {
            // This bin cannot fit the next item; penalize proportional to how much we need the space.
            score += 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Reward bins that leave exactly enough space for the next item (synergy).
            score -= 15.0 * (1.0 - (fit_margin / bin_capacity as f64));
        }
    }

    // Stream progression adjustment:
    // Early in the stream, be more conservative (avoid opening new bins).
    // Late in the stream, be more aggressive to clear remaining items.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening new bins early, diminishing as we approach the end.
        score += 80.0 * (1.0 - progress).powf(1.5);
    }

    // Encourage balance: penalize bins that deviate significantly from the mean_residual.
    let dev = (post - mean_residual).abs();
    score += 5.0 * (dev / bin_capacity as f64);

    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid the penalty of opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
