pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 is perfect (Best Fit), high is wasteful.
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        // If we have other options, penalize opening a new bin based on how many bins are already open
        // and the current progress of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 * (1.0 - progress);
        score += (open_bins_count as f64) * 2.0;
    }

    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it later.
    // If post_residual is smaller than next_item_size, we create "dead space" that cannot be filled.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Global State: Penalize bins that deviate significantly from the mean residual.
    // This encourages keeping the density of all bins somewhat uniform (Best Fit behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Scarcity: If this is the only bin that fits, prioritize it strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Hard threshold: Avoid creating "sliver" residuals (e.g., 1-5) which are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating a "dead zone": if the remaining space is too small to fit 
    // likely future items (modeled by mean_residual), we penalize the placement.
    // We use a non-linear exponential penalty to discourage tiny gaps.
    if post_res > 0.0 && post_res < mean_residual * 0.5 {
        score += (mean_residual / (post_res + 1.0)).powf(1.5);
    }

    // Lookahead logic: if the next item fits into this bin's post_residual, 
    // reward the bin heavily to encourage packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
