    }

    // Progression logic: As the stream nears the end, become more conservative 
    // about opening new bins. If current bin is empty (new bin candidate),
    // apply a penalty that increases as the stream progresses.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress.powi(2));

        // If we are forced to open a new bin despite fitting bins being available,
        // penalize it unless the fitting bins are extremely inefficient.
        if fitting_bins_count > 0 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Interaction between open_bins_count and post_residual:
    // Avoid fragmented space when many bins are already open.
    score += (open_bins_count as f64) * (post_res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

