    // only accept it if we cannot fit the item well in existing bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Dynamically reduce new bin penalty as we near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;
    }

    // 6. Mean Residual Balance: Favor bins that stay close to the system-wide 
    // mean residual to keep distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
