    // We use a quadratic penalty for the post_residual to favor near-zero gaps.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space,
    // reward this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = (post_residual - next_item_size) as f64;
        score -= (100.0 - gap_after_next).powf(1.2); 
    }

    // 3. New Bin Threshold: If this is a new bin, penalize it based on how many 
    // open bins currently exist. This prevents fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 25.0;
    }

    // 4. Mean Residual Balancing: If the bin's post_residual is significantly 
    // lower than the global mean, it's a "tight" bin. Reward it to keep 
    // the mean residual low across the system.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 5.0;
    }

    // 5. Urgency Constraint: If this is the only bin that can fit the current item, 
    // force its priority by lowering the score significantly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // 6. Progressive Tightening: As the stream nears the end, become more 
    // aggressive about closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
