pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that create "orphaned" space (e.g., < 10)
    // unless we are near the end of the stream.
    let orphan_penalty = if post < 10.0 && post > 0.0 {
        25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Reward bins that accommodate the next item (lookahead)
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Balance between Best-Fit (minimizing post_residual) and bin consolidation.
    // As progress increases, we become more aggressive about filling bins tightly.
    let base_score = post.powf(1.2 + (0.5 * progress));

    // If this is the only bin that fits the current item, prioritize it to avoid
    // opening a new bin unnecessarily, unless the fit is extremely poor.
    let fit_urgency = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -20.0
    } else {
        0.0
    };

    // Penalize the "New Bin" candidate (bin_residual == bin_capacity)
    // increasingly as we progress through the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        30.0 + (40.0 * progress)
    } else {
        0.0
    };

    base_score + orphan_penalty + lookahead_reward + fit_urgency + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
