        score += 15.0 + (progress * 40.0).powf(1.5);
    } else {
        // Reward bins that leave a residual which is a perfect multiple or close to 
        // the next item size to encourage packing efficiency.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= (1.0 / (1.0 + diff)) * 10.0;
        }

        // Penalize bins that create "small, unusable" slivers (less than 10 units)
        // unless it's a perfect fit (post_residual == 0).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Discourage spreading items across too many bins if they could fit in fewer.
        // If fitting_bins_count is high, we favor bins that bring the mean_residual
        // closer to the item_size to keep the pack dense.
        if fitting_bins_count > 1 {
            let density_diff = (post_residual as f64 - mean_residual).abs();
            score += density_diff * 0.2;
        }
    }

    // Curvature: Penalize large post_residuals more heavily in the late-stage stream
    // to force tighter packing when we are running out of items.
    score += (post_residual as f64).powf(1.2) * (0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space) quadratically.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Class Logic: Reward placements that leave a residual which is a multiple
    // of common item sizes or fits the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect alignment with next item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs());
        } else {
            // Penalize if the next item is forced to open a new bin
            score += 25.0;
        }
    }

    // 3. Fragmentation Control: If post_residual is very small (< 10), it creates "dead space"
    // that rarely fits future items. Penalize this unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one heavily.
    // Otherwise, favor keeping the mean_residual high to accommodate future large items.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Urgency: If this is the last chance for the current item, reduce the penalty
    // for poor fit to avoid unnecessary bin creation later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 6. Progress Scaling: As the stream nears the end, be more aggressive with packing
    // to minimize the number of bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
