    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer bins that leave less room (Best Fit)
    let mut score = post_res;

    // Penalty for creating "dead space": residuals between 1 and 9 are often unusable.
    // We apply a non-linear penalty for small, difficult-to-fill remainders.
    if post_residual > 0 && post_residual < 10 {
