    // Dynamic thresholding: as we near the end of the stream, we become more aggressive
    // about filling existing bins to avoid opening new ones.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += progress * density_factor * 2.0;

    // If this is a new bin candidate (bin_residual == bin_capacity), 
