pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit Decreasing logic (minimize post_residual).
    // We add non-linear penalties to prevent "fragmentation" (small, unusable residuals).
    // A residual between 1 and 9 is often a "dead zone" for items 10-80.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        100.0 / (post_residual as f64 + 1.0)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the mean_residual of other bins
    // to keep the packing density balanced across the set.
    let balance_penalty = (post_res - mean_residual).powi(2) * 0.1;

    // Lookahead logic: if the next item is large, penalize small residuals in current bin
    // to save space for the upcoming item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 2.5
    } else {
        0.0
    };

    // Progress-based scaling: As we reach the end of the stream, we become more 
    // aggressive about using existing bins (penalizing new bin creation).
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 + (progress * 150.0)
    } else {
