    };

    // If this is the only bin that can fit the item, give it a significant discount.
    let last_chance_bonus = if fitting_bins_count == 1 && bin_residual >= item_size {
        -50.0
    } else {
        0.0
    };

    post_res + dead_space_penalty + balance_penalty + lookahead_penalty + new_bin_penalty + last_chance_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
