    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tighter fits for the next item
        score -= (100.0 - diff) * 0.5;
    }

    // 4. Mean Residual balancing:
    // If this bin's post_residual is significantly better than the global mean, reward it.
    // This helps stabilize the distribution of space across open bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 5. Urgency factor:
    // If this is the only bin that can fit the item, we must take it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 6. New Bin Threshold:
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the current open bins are all very poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to encourage packing into existing ones.
        score += 60.0;

        // If we are late in the stream, opening a new bin is more expensive.
        score += (step_index as f64 / total_items as f64) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
