pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation exponentially as the stream progresses
    let new_bin_penalty = if is_new_bin {
        25.0 + (progress.powf(2.0) * 50.0)
    } else {
        0.0
    };

    // Calculate "tightness" of the fit: lower post_residual is generally better (Best Fit),
    // but we penalize very small residuals (e.g., 1-4) that are unlikely to be filled later.
    let fit_quality = post_residual as f64;
    let fragmentation_penalty = if post_residual > 0 && post_residual < 8 {
        (8.0 - post_residual as f64) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if we know the next item, prioritize bins that can accommodate it.
    // If next_item_size fits in the current post_residual, reward this bin.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Global state awareness: if we have too many open bins, penalize opening new ones more aggressively.
    let open_bins_pressure = (open_bins_count as f64).sqrt() * 2.0;

    // Combine factors:
    // We want the lowest score, so bonuses are negative.
    let score = fit_quality 
        + fragmentation_penalty 
        + new_bin_penalty 
        + lookahead_bonus 
        + open_bins_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
