    // If the post_residual is between 1 and 9, it is highly likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: Reward bins that fit the next item perfectly (or close to it)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        // If the next item fits perfectly, prioritize this bin heavily
        if gap_after_next == 0 {
            score -= 40.0;
        } else if gap_after_next < 10 {
            // Penalize small gaps resulting from the next item
            score += 20.0;
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Base cost for being forced to open a new bin
        }
    }

    // 4. Density Balancing: Favor bins that keep the mean residual of the system low
    // If the current bin's residual is significantly higher than the mean, we penalize it
    // to force packing into tighter bins first (Best Fit logic).
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive Best-Fit with 2-step lookahead and residual balancing.

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, 
    // prioritize this bin to maximize bin density (Best-Fit principle).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation avoidance: Penalize post_residuals that are too small to hold 
    // common items (below 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Balancing: If post_residual is significantly lower than the global mean_residual,
    // we favor creating a tighter pack to keep the mean_residual stable.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize filling existing bins over opening new ones (open_bins_count pressure).
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 6. Last-chance logic: If this is the only bin that fits the current item, 
    // strongly incentivize choosing it regardless of post_residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing dynamic variant)
    // We prioritize keeping the post_residual as small as possible (Best Fit),
    // but penalize creating "fragmented" bins that cannot fit the next item.

    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless the current fit is extremely poor (Best Fit bias)
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if we have many bins already open
        // This thresholding prevents premature bin opening.
        score += 25.0 + (open_bins_count as f64 * 0.5);
        if item_size < 40 {
            score += 30.0;
        }
    }

    // 2. Lookahead: Penalize if the current bin would be unable to fit the next item
    // but another bin could have potentially accommodated it better.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize "dead space" that cannot fit the immediate next item
            score += 15.0;
        }
    }

    // 3. Global State: Encourage packing into bins that are already "tight"
    // If we have many open bins, try to consolidate by favoring bins with lower residuals.
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 4. Scarcity: If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // 5. Time Horizon: As we reach the end of the stream, prioritize space utilization
    // more aggressively to close out the remaining items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as they are hard to fill.
    // We use a quadratic penalty for post_residual < 10 to encourage tighter fits.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res).powi(2) * 5.0
    } else {
        0.0
    };

    // Factor in the next item: if post_residual cannot fit next_item_size, we penalize the current choice
    // unless the bin is already very full (high efficiency).
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * (1.0 - progress) * 2.0
    } else {
        0.0
    };

    // Dynamic preference: early in the stream, favor Best Fit (low post_residual).
    // Late in the stream, prioritize closing bins to reduce open_bins_count.
    let efficiency_weight = 1.0 + (progress * 3.0);

    // Base score: prioritize smaller post_residual (Best Fit principle).
    let mut score = post_res * efficiency_weight + gap_penalty + lookahead_penalty;

    // If this is a new bin (bin_residual == bin_capacity):
    // Heavily penalize opening new bins unless no other bin can fit the item
    // or the existing bins are extremely crowded (mean_residual is very low).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (100.0 - mean_residual) * 2.0;
        } else {
            score -= 50.0; // Essential to open a new bin if no other choice
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "unusable" small gaps (1..9) which are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Best Fit Decreasing logic: heavily favor bins that result in near-zero residuals
    // Penalize new bin creation unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // Harmonic Lookahead: If next_item_size is large, avoid leaving a residual that is just slightly too small
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Cannot fit next item, penalize this bin slightly
            score += 15.0;
        } else {
            // Can fit next item, reward this bin
            score -= 25.0;
        }
    }

    // Adaptive pressure: If we are near the end of the stream, prioritize space consolidation
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    // Harmonic balance: favor bins whose residuals are closer to the global mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space avoidance: Penalize gaps that are too small to fit typical future items (< 10)
    // or gaps that are slightly larger than the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
