    } else {
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 3. Global efficiency: Favor bins that keep the mean residual low, 
    // discouraging creation of bins that significantly deviate from the average.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 4. Stream progression: As we approach the end, prioritize tight packing over distribution.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize fragmentation: If the post_residual is small but not zero, it's often a "dead zone" 
    // for future items (which are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item can fit in the current post_residual, 
    // prioritize this bin highly to consolidate items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if this is the only bin that can fit the current item (Best Fit logic)
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 3. Balance usage across bins: If this bin's residual is significantly lower than the mean,
    // it is a "tight" bin. We prefer filling tight bins first to keep others open for larger items.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 4. New bin management: If this is a new bin (bin_residual == bin_capacity), 
