    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening a new bin heavily unless we have very few options or the item is large.
        score += 60.0 + (item_size as f64 * 0.5) + (progress * 20.0);
    }

    // 5. Prefer bins that keep the post_residual close to the mean_residual of other bins
    // to maintain a uniform distribution of available space.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in smaller post_residual
    // (Already captured by base score, but we refine it).

    // 2. Penalize opening a new bin prematurely
    if bin_residual == bin_capacity {
        // Only open a new bin if the item is large or if we have very few options, 
        // otherwise make the penalty high.
        score += 45.0; 
        if item_size > 70 { score -= 20.0; }
        if open_bins_count == 0 { score -= 50.0; }
    }

    // 3. Lookahead: If the next item is large, avoid creating a residual that is just slightly too small
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // This bin will likely be unusable for the next item, penalize
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Best Fit for lookahead)
            score -= (bin_capacity - post_residual) as f64 * 0.2;
