    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Tighten packing in the final phase
        if post_residual < 10 { score -= 15.0; }
    }

    // 5. Handling 'Last Chance': If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
