}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Normalize stream progression
    let progress = step_index as f64 / total_items as f64;

    // The objective is to minimize score.
    // 1. Primary penalty: post_residual (Best Fit principle).
    // 2. Non-linear coupling: Exponentially penalize small post_residuals as the stream nears end.
    // 3. Lookahead penalty: If next_item_size is large, avoid bins that leave a small, unusable gap.
    // 4. Strategic new bin opening: Only open a new bin if the current fit is extremely poor relative to mean_residual.

    let mut score = post_residual as f64;

    // Non-linear penalty for leaving small gaps that cannot fit common future items (lookahead).
    // If post_residual is < next_item_size, it creates a "dead zone" for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic pressure: As the stream progresses, prioritize tighter packing to reduce open_bins_count.
    // We penalize the post_residual more heavily as progress approaches 1.0.
    score += (post_residual as f64).powf(1.2) * progress;

    // Penalty for creating a new bin:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We apply a cost based on the number of open bins and the average space wasted.
    if bin_residual == bin_capacity {
        // Only open a new bin if fitting_bins_count is low, 
        // to avoid fragmentation across too many active bins.
        score = (mean_residual * 0.8) + (open_bins_count as f64 * 2.0);
    } else {
        // If it's an existing bin, reward bins that align with the mean_residual.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Final constraint: if this is the only bin that fits the current item, 
        // significantly lower its score to prevent opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // A bin is a new bin if bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit strategy).
    // Lower post_residual means tighter packing.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
