        // Penalty for using too many bins early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64) * (1.0 - progress) * 2.0;

        // Penalty for bins that deviate significantly from the mean residual (load balancing)
        let residual_diff = (bin_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

