    // We penalize larger post-residuals quadratically to discourage fragmentation.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Class logic: incentivize filling bins to specific thresholds
    // If post_residual is small, it's often better to keep it that way.
    // If post_residual is large, we check if it can accommodate the next_item.
    if next_item_size > 0 {
