    // unusable "dead space" as items are at least 10. Penalize these gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0;
    }

    // 3. Open Bin Pressure: Discourage opening a new bin if other bins are available.
    // If this is the "new bin" candidate (bin_residual == bin_capacity), add a penalty
    // proportional to how many bins are currently open and how many could fit the item.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 20.0;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tightness bias: Favor bins that are already "tight" (low mean_residual) 
    // to keep the bin fill levels consistent.
    score += mean_residual * 0.5;

    // 5. Progression weighting: As we approach the end of the stream, be more 
    // aggressive about using existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
