        score -= 20.0;
    } else if post_residual < 10 {
        score += 10.0; // Penalize "sliver" space that is likely unusable
    }

    // 4. Mean Residual Balancing: Favor bins that align with the global average to keep packing density uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 6. Progress Scaling: As the stream nears completion, prioritize tighter packing to close bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

