    }

    // 4. Scarcity/Efficiency: If this is the last bin that can fit the item, reward it to save others.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Control: Dynamically adjust the cost of opening a new bin based on progress.
    // As we reach the end of the stream, be more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // 6. Packing Density: Favor bins that are already well-filled to keep the number of open bins low.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
