    // We penalize larger post_residuals to encourage filling bins as much as possible.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits into the remaining space, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
