        // and we want to preserve smaller gaps elsewhere.
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Harmonic Fragmentation Control: Avoid creating "dead" spaces that are too small for any likely item.
    // Given sizes are 10-80, a residual < 10 is almost always useless.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
