    // 5. Fitting Logic: If this is the last bin that can fit the item, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Deviation: If this bin is significantly emptier than the average, favor placing here to balance.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score -= residual_deviation * 0.2;

    // 7. Progression scaling: As we reach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
