    }

    // 5. Critical threshold for single-choice bins
    // If fitting_bins_count == 1, this is the only bin that can take this item.
    // We should prioritize filling this bin unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual < 20 {
