pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" that is too small for most items.
    // As progress increases, we become more aggressive about minimizing fragmentation.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 + progress);
    }

    // Lookahead logic: if the next item is large, avoid leaving a residual that is 
    // too small to accommodate it, especially if we are in the later stages of the stream.
    if next_item_size > 0 && post < next_item_size as f64 {
