    if bin_residual == bin_capacity {
        // Only consider a new bin if we have very few good options, 
        // weighted by how far along we are in the sequence.
        score += 15.0 + (fitting_bins_count as f64 * 5.0) - (progress * 10.0);
    }

    // Bias towards utilizing bins that are already partially filled to keep the
    // distribution of residuals tighter (keeping mean_residual lower).
    score += (mean_residual - post) * 0.5;

    // Favor bins that have fewer opportunities for future items if the current 
    // fit is already tight (Best Fit Decreasing style).
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
