    score += residual_penalty * 0.2;

    // 5. Progression scaling: As the stream nears the end, prioritize tight packing 
    // to avoid leaving trailing items in new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
