    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the residual space left after placement; smaller is better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone": if the remaining space is too small to fit typical future items
    // but large enough to be wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits perfectly into the post-placement residual, 
    // prioritize this bin heavily (negative score).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // If this is the only bin that can fit the item, we are forced to use it.
    // Discourage opening a new bin if an existing one is available.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if there are existing options.
            score += 200.0 + (open_bins_count as f64 * 5.0);
        }
    } else {
        // Encourage filling bins that are already below the mean_residual to consolidate space.
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Progress-based weighting: As the stream nears the end, be more aggressive about 
    // closing bins (Best Fit) to avoid unnecessary new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the remaining space. Smaller is usually better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation): 
    // If post_residual is small but > 0, it's often hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily (negative score).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // Global state: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // New Bin Handling:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only want to open a new bin if the current open bins are "bad" fits.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score = 45.0; 

        // If we have many open bins that are nearly full, don't open a new one.
        if mean_residual < 15.0 {
            score += 50.0;
        }

        // If the current item is very large, it might be worth opening a new bin
        // to avoid crowding existing bins.
        if item_size > 70 {
            score -= 10.0;
        }
    } else {
        // For existing bins, favor those that bring the residual closer to the mean.
        // This keeps the bins balanced.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.1;

        // If this is the only bin that fits, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of "sliver" gaps (residual space < 10) that are hard to fill later.
    // As the stream progresses, we become more risk-averse regarding slivers.
    let sliver_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Reward bins that can accommodate the next item (lookahead).
    // If the next item fits in the current post_residual, reduce the score.
    let lookahead_bonus = if next_item_size > 0 && (post_residual >= next_item_size) {
        (next_item_size as f64 / bin_capacity as f64) * 20.0
    } else {
        0.0
    };

    // Discourage opening new bins unless the fit is extremely poor in existing bins.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual is high (bins are under-utilized)
        // or if there are no bins that can fit the current item.
        let efficiency_factor = (mean_residual / bin_capacity as f64) * 50.0;
        let scarcity_factor = if fitting_bins_count == 0 { -20.0 } else { 30.0 };
        efficiency_factor + scarcity_factor
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residual (Best Fit principle).
    // Non-linear coupling: square the post_residual to heavily penalize large gaps,
    // modulated by progress to tighten constraints toward the end of the stream.
    let base_score = post.powf(1.2 + progress);

    base_score + sliver_penalty - lookahead_bonus + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "dead space" that cannot fit typical items (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
