pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best Fit Decreasing logic)
    // We heavily penalize large post_residuals.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, reward this bin.
    // This is the core "2-step lookahead" component.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward fits that leave very little space after the second item (perfect pair).
            let secondary_residual = post_residual - next_item_size;
            score -= (100.0 - secondary_residual as f64) * 2.5;
        } else {
            // Penalize if the next item will force a new bin because this bin is now too small.
            score += 20.0;
        }
    }

    // 3. Fragmentation Avoidance: Penalize residuals that are too small to fit any common future item (under 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Global State Awareness:
    // If this is the only bin that fits the current item (fitting_bins_count == 1), 
    // force its selection by lowering the score significantly.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity (New Bin), apply a high base cost to discourage 
    // opening new bins unless the current open bins result in very poor fit scores.
    if bin_residual == bin_capacity {
        score += 65.0;
        // Adjust new bin cost based on how many bins are already open to prevent runaway fragmentation.
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current average density.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
