    // We want to minimize this to fill bins tightly.
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // If post_residual is small but > 0, it's hard to fill.
    // If post_residual is 0, it's a perfect fit.
    if post_residual > 0 {
        score += (post_res * 0.5).powf(1.5);
    }

    // Lookahead logic: If the next item is large and won't fit in this residual,
    // we should prioritize bins that leave more room for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.2;
