    }

    // Progression logic: As the stream nears the end, we become more desperate 
    // to avoid opening new bins, so we penalize the "new bin" candidate (bin_residual == 100)
    // and favor existing bins more aggressively.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalty increases as we progress through the stream.
        score += 20.0 + (progress * 50.0);

        // If there are other bins that could fit the item, strongly penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // For existing bins, reward bins that are closer to the mean residual
        // to keep usage balanced across open bins.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Scale by open_bins_count to discourage excessive fragmentation
    score += (open_bins_count as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

