    // 4. Harmonic/Modulo pressure: Penalize residuals that are non-multiples of common item sizes (e.g., 20, 25, 33).
    // This helps organize bins into specific "classes" based on remaining capacity.
    if post_residual % 20 == 0 {
        score -= 30.0;
