    post_res + gap_penalty + lookahead_affinity + new_bin_bias + density_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-Residual Balancing
    // Strategy: Penalize small "fragment" residuals that are difficult to fill, 
    // while prioritizing bins that can accommodate the lookahead item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": residuals that are too small to fit typical items (10-30)
    // but large enough to waste capacity.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If next_item_size fits in post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Harmonic weight: Favor bins that are "tightly packed" relative to the mean.
    // This helps stabilize the bin distribution.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // 4. Threshold for opening new bins: 
    // If this is the new bin candidate (residual == capacity), penalize it 
    // unless all other bins are poor fits (fitting_bins_count is low).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to encourage consolidation.
        score += 35.0;

        // If we have few bins open, opening a new one is less catastrophic.
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // If this is the last bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 5. Progression factor: In late stages, become more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual to fill bins tightly, but penalize creating "unusable" 
