    // Lookahead logic: if the next item could have fit in the current residual,
    // but we are choosing to place the current item here, penalize if it blocks
    // a better fit for the next_item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0; // Reward leaving space for the next item
    }

    // Pressure factor: if we have many bins open, penalize opening a new one heavily.
