        // If there are other bins that could fit this item, make opening a new one 
        // very expensive unless the fitting bins are nearly full.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // For existing bins, reward bins that are already closer to being "full"
        // to consolidate usage.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Temporal smoothing: as we approach the end of the stream, prioritize 
    // closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the current placement leaves a gap that perfectly fits the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item
            let gap_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap_diff * 2.0);
        } else {
            // Penalty if the next item cannot fit in this bin anymore
            score += 20.0;
        }
    }

    // 3. Fragmentation Control: If this is the last bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score += 80.0;

        // If there are many open bins, we are already fragmented; be more conservative about opening new ones.
        score += (open_bins_count as f64) * 2.5;
    }

    // 5. Mean Residual Balancing: Prefer bins closer to the global mean to keep space uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 6. Progress Scaling: As the stream nears completion, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
