    // If post_residual is small but not zero, it's often better to have filled it completely.
    // We penalize values that cannot accommodate common small items (e.g., < 10).
    if post_res > 0.0 && post_res < 10.0 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead coupling: If next_item_size is large, avoid leaving small residuals
    // that cannot fit the next item.
    if next_item_size > 0 && (next_item_size as f64) > post_res {
        score += 40.0 * (1.0 - (post_res / (next_item_size as f64 + 1.0)));
    }

    // Stream progression adjustment:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    // If bin_residual == bin_capacity (New Bin candidate), apply a progressive penalty.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we progress through the stream
        // to encourage packing into existing bins.
        score += 50.0 * (1.0 + progress * 2.0);

        // If there are bins that could fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Encourage using existing bins that are already "half-full" or more,
        // weighted by the mean residual of current bins.
        let fill_ratio = 1.0 - (post_res / bin_capacity as f64);
        score -= 15.0 * fill_ratio * (1.0 - progress);
    }

    // Interaction term: Penalize high mean_residual if we are creating a new bin
    // that would further increase the average wasted space.
    if bin_residual == bin_capacity && mean_residual > 30.0 {
        score += mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
