    // 3. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // average efficiency of the current packing state.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. New Bin Threshold: If we are forced to open a new bin, penalize it 
    // based on the current packing density to discourage premature bin opening.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are already quite full.
        if mean_residual > 20.0 {
            score += 40.0;
        } else {
            score += 70.0;
        }
    }

    // 5. Scarcity Logic: If this is the only bin that can fit the item, 
    // reward placing it here to preserve open bins for future items.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
