pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit).
    // Penalize empty bins heavily unless we have no other choice.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0;
        }
        return score;
    }

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of common item sizes.
    // This helps pack items that "fit" together to leave zero space.
    let remainder = post_residual % 10;
    score += (remainder as f64) * 2.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual,
    // prioritize this bin to maximize current packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 150.0;
    }

    // 4. Tightness Constraint: If this is the last bin that can fit the item,
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // 5. Mean residual equilibrium: Avoid creating bins that are significantly 
    // worse than the average residual to maintain homogeneous bin states.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.5;

    // 6. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Heavily penalize small, unusable gaps.
    // If post_residual is between 1 and 9, it is extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins if we have many open bins already.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;

        // If we have fitting bins, opening a new one is almost always bad unless
        // the existing bins are all "full" (mean_residual is low).
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Density Optimization: Favor bins that align with the global mean_residual.
    // This helps keep bins balanced in their remaining capacity.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 5. Last Chance Heuristic: If this is the only bin that fits the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // 2. Lookahead Synergy: Reward bins that become perfect matches for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // Strong reward for perfect 2-step fit
        } else if post_residual > next_item_size {
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 60.0; // Penalty: cannot fit next item
        }
    }

    // 3. Fragmentation Control: Avoid creating bins with residual space significantly
    // lower than the mean residual unless it's a very tight fit.
    if post_residual < (mean_residual * 0.4) as u32 && post_residual > 0 {
        score += 25.0; 
    }

    // 4. New Bin Thresholding: Adjust the cost of opening a new bin
    // If it's a new bin (bin_residual == bin_capacity), add a bias based on
    // how many other bins could have taken the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 80.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // If no other bins fit, make it the preferred option
            score -= 10.0;
        }
    }

    // 5. Progression Smoothing: As the stream nears the end, favor tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "fragmented" small residuals (Best Fit Decreasing intuition)
    // Residuals under 10 are often dead space unless they are exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid small post_residuals.
    // If we have a next item, we want to ensure we leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // 3. Dynamic Thresholding: As we approach the end of the stream, 
    // become more aggressive in filling bins to capacity.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. Penalty for opening new bins:
    // Only open a new bin if the current fit is very poor (e.g., post_residual is large)
    // or if we are forced to.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavy penalty for opening a new bin if an existing one can fit the item
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // Baseline cost for opening a new bin when necessary
            score -= 5.0;
        }
    }

    // 5. Balance the number of open bins:
    // Penalize increasing the number of open bins if we have many already.
    if open_bins_count > 5 {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragmented" bin (a bin with very small residual).
    // If post_residual is > 0 and < 10, it's likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= (next_item_size as f64) * 2.5;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, we become more conservative about opening new bins.
    // We penalize opening a new bin (where residual == capacity) more heavily as progress increases.
    if residual == (bin_capacity as f64) {
        score += 15.0 + (progress * 40.0);
    }

    // Coupling with mean_residual:
    // If the current bin's residual is significantly better than the global average, 
    // reward it to keep bins consistently tight.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.5;
    }

    // Final adjustment: penalize having too many open bins if we are deep in the stream.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

