    // We prioritize keeping the post_residual small to maximize density.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave "clean" remainders
    // If post_residual is a multiple of 10, it's more likely to fit future items.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 3. Lookahead Synergy: If the next item fits perfectly in the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0; // Strong reward for perfect packing
        } else if gap < 10 {
            score -= 15.0; // Moderate reward for tight packing
        }
    }

    // 4. Scarcity Management: If this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 5. New Bin Thresholding: Penalize opening a new bin unless the current state is very poor.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins already and the average density is dropping,
        // or if we are at the very start of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 30.0; 
        if open_bins_count < 2 {
            score -= 10.0;
        }
        if mean_residual < 20.0 {
            score += 20.0;
        }
    }

    // 6. Penalty for "Fragmenting" the mean residual: 
    // Avoid creating bins that significantly deviate from the global average residual.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10, as items are >= 10).
    // If post_residual is in the range [1, 9], it is effectively wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0 / (post_residual as f64 + 0.1);
    }

    // 2. Prioritize tight fits (Best Fit principle).
    // We reward bins that leave very little space, but avoid the "near-empty" trap.
    score += (post_residual as f64) * 0.5;

    // 3. Penalty for opening a new bin when existing bins have capacity.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Apply a heavy penalty to force filling existing bins unless they are all poor fits.
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Lookahead adjustment: If the next item is large, favor bins that leave enough space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }

        // 5. Pressure against high open_bins_count: favor filling bins that are already "half-full"
        // to consolidate usage.
        if (bin_capacity - bin_residual) < (bin_capacity / 2) {
            score -= 5.0;
        }
    }

    // 6. Final normalization: Favor bins that leave room for future items if the stream is early.
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation): 
    // If post_residual is small but > 0, it's often a waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: Reward bins where the post_residual can accommodate the next item.
    // If next_item_size is 0 (end of stream), we prioritize filling bins completely (Best Fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for a "Perfect" or "Tight" follow-up fit.
            score -= (next_item_size as f64) * 1.5;
        }
    }

    // Pressure to consolidate: If we have many open bins, penalize opening a new one 
    // unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Dynamic penalty for opening a new bin based on how many bins are already active.
            score += (open_bins_count as f64) * 5.0;
        }
    } else {
        // Favor bins that align with the current mean residual to keep bin states uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Criticality check: If this is the only bin that fits the item, make it the top choice.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // Progress scaling: As we reach the end of the stream, tighten the fit requirement (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" early in the stream, 
    // favoring tight fits (Best Fit principle).
    // post_residual^2 penalizes large gaps heavily.
    score += (post_residual as f64).powi(2) * 0.1;

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin heavily to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // New bin logic: If this is an empty bin (bin_residual == bin_capacity),
    // only choose it if the current fitting bins are very poor (high post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no good options or the stream is ending
        // and we want to consolidate.
        score += 25.0 + (progress * 10.0);
    } else {
        // If this is a tight fit (post_residual < 10), prioritize it strongly.
        if post_residual < 10 {
            score -= 15.0;
        }

        // If this is the last chance to fit the item in an existing bin,
        // reward it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Global state adjustment: If many bins are open, try to pack tighter
    // to close bins sooner.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual balance: Avoid bins that deviate too far from the average
    // to keep the bin distribution uniform.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
