        score += (mean_residual * 0.5) + (1.0 - progress) * 20.0;
    } else {
        // Reward placements that result in a "tight" fit, but penalize leaving tiny gaps
        // that are unlikely to accommodate the next item.
        let tightness_penalty = (post_residual as f64).powf(1.5);
