pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for creating a "dead zone" (very small residual) that is hard to fill later.
    // We penalize residuals in the [1, 9] range heavily, as they are unlikely to fit future items.
    let dead_zone_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, we want to keep larger residuals available.
    // If post_residual is too small for the next item, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post < (next_item_size as f64) {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Global pressure: as the stream progresses, we want to be more aggressive about packing
    // tightly (Best Fit behavior) to avoid opening new bins late in the game.
    let tightness_pressure = (post / bin_capacity as f64) * (1.0 - progress) * 20.0;

    // Favor bins that align with the current mean_residual to keep bin states uniform.
    let uniformity_bonus = (post - mean_residual).abs() * 0.1;

    // Decision Logic:
    // If this is a new bin (bin_residual == bin_capacity), score it with a base cost.
    // The base cost increases as we reach the end of the stream to prevent opening new bins.
    let base_score = if bin_residual == bin_capacity {
        45.0 + (progress * 30.0)
    } else {
        post
    };

    base_score + dead_zone_penalty + lookahead_penalty + tightness_pressure + uniformity_bonus
}

