pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: lower post_residual is generally better (tighter packing).
    // We penalize large post_residual values to avoid wasting space.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead optimization: 
    // If the next item can fit in the current post_residual, we reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Avoid small "orphaned" residuals:
    // If post_residual is small but not zero, it's often unusable for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Strategic new bin opening:
    // If this is a new bin (bin_residual == bin_capacity), only open if existing bins are poor fits.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0;
        } else {
            // Penalize opening a new bin if we have many bins with decent space.
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 5. Global state pressure:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 30.0;
    }

    // 6. Fitting bin count awareness:
    // If this is the only bin that can fit the item, we must take it (lower score).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual (Best Fit strategy).
    // We want to minimize this to keep residual space small (tight packing).
    let mut score = post_res;

    // Penalty for opening a new bin:
    // Only open a new bin if the residual space in existing bins is highly suboptimal
    // or if the stream is nearing its end.
    if is_new_bin {
        // High base penalty to discourage opening new bins prematurely.
        score += 45.0;
        // As the stream progresses, the cost of opening a new bin decreases slightly 
        // to encourage finishing the packing process efficiently.
        score -= (progress * 15.0);
    } else {
        // Optimization: Favor bins that leave a residual space capable of 
        // accommodating the next item (lookahead).
        if next_item_size > 0 && post_res < next_item_size as f64 {
            // Penalize bins that create "dead space" too small for the next item.
            score += (next_item_size as f64 - post_res) * 1.5;
        }

        // Penalty for leaving a bin "partially full" such that it deviates significantly 
        // from the mean residual of open bins (encouraging uniform distribution).
        let dev = (post_res - mean_residual).abs();
        score += dev * 0.5;
    }

    // If this is the last chance to fit an item in an existing bin, 
    // heavily incentivize taking that fit over a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Non-linear coupling: As the stream progresses, penalize larger residuals
    // more aggressively to force tighter packing for remaining items.
    score += (post_res * progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic Class logic: Reward placing items into bins where the post_residual 
