    }

    // Dynamic pressure: As the stream nears the end, prioritize closing bins
    // by penalizing small residuals less to encourage completion.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    // Final constraint: If this is the only bin that fits, heavily reward it
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
