    }

    // Penalty for opening a new bin: Only open if the current fit is extremely poor 
    // (e.g., leaving a very small residual that prevents future packing).
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, discourage opening more
        score += (open_bins_count as f64) * 2.0;
    }

    // Balancing: Favor bins where the post_residual is close to the global mean_residual
