}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    // We heavily penalize small fragments that are unlikely to accommodate future items
    // (the "fragmentation penalty").
    let mut score = post;

    // Non-linear coupling: If the post_residual is small (e.g., < 15), it creates 
    // "dead space" that is hard to fill. Penalize this more as the stream progresses.
    if post < 15.0 {
        score += (15.0 - post).powf(1.5) * (1.0 + progress * 2.0);
    }

    // Lookahead: If next_item_size exists, penalize bins that cannot fit the next item
    // after placing the current one.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // New bin strategy: If this is a new bin (bin_residual == bin_capacity), 
    // only accept if fitting_bins_count is low or if current open bins have
    // very low mean_residual (meaning they are already tightly packed).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can fit the item,
            // unless all open bins are extremely tight.
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // If no other bin fits, this is the only option, normalize to low score.
            score = 5.0;
        }
    } else {
        // Favor bins that align with the mean usage to keep residual variance low.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
