    // If bin_residual == bin_capacity, this is the "new bin" candidate call.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Best-Fit Decreasing logic: reward smaller post_residual (tighter fit)
    // Non-linear scaling: square the residual to penalize large gaps exponentially
    let fit_score = (post * post) / 100.0;

    // Lookahead logic: if we know the next item, reward bins that can accommodate it.
    // If next_item_size > post_residual, the current placement creates "dead space" for the next item.
    let lookahead_penalty = if next_item_size > 0 && next_item_size > post_residual {
