    } else {
        0.0
    };

    // Interaction term: penalize deviation from the mean_residual to keep bins balanced
    let balance_penalty = (post - mean_residual).abs() * 0.2;

    new_bin_penalty + fit_score + lookahead_penalty + scarcity_reward + balance_penalty
}

