    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic post-fit space. 
    // We want to minimize post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is too empty early on, 
    // but allow flexibility as the stream progresses.
    let progress = step_index as f64 / total_items as f64;

    // If the bin is new (bin_residual == bin_capacity), add a significant penalty
    // to discourage opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // Lookahead logic: if next_item_size is known, penalize placements that 
    // leave insufficient space for the next item, or reward placements that 
    // leave exactly enough space (Perfect Fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward the "Perfect Fit" for the next item
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                // Penalize large gaps if the next item could have fit better elsewhere
                score += (post_residual - next_item_size) as f64 * 0.5;
            }
        } else {
            // Penalize leaving a gap that is useless for the next item
            score += 15.0;
        }
    }

    // Heuristic: Prefer bins that are closer to the mean residual of all open bins
    // to keep the bin fill levels uniform (reducing entropy).
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Last chance logic: If this is the only bin that can fit the item, 
    // we should prioritize it highly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

