    // 2. Penalty for creating "dead space": if post_residual < 10, it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - progress);
    }

    // 3. Lookahead awareness: If next_item can fit in this post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

