        score = 85.0 + (open_bins_count as f64 * 2.0) - (mean_residual * 0.5);
    } else {
        // If this bin is nearly full, reward it to consolidate space.
        if post_residual < 5 {
            score -= 20.0;
        }
        // Penalize bins that deviate significantly from the mean_residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit logic).
    let mut score = post;

    // Penalty for creating "dead zones": if post_residual is small but > 0, it's often worse than 0.
    // We penalize small residuals more heavily as the stream progresses to consolidate packing.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress);
    }

    // Lookahead integration: if a future item is large, favor keeping larger residuals (smaller scores).
    // If next_item_size is large, we want to leave room for it.
    if next_item_size > 0 {
        let next_req = next_item_size as f64;
        if post < next_req {
            score += (next_req - post) * 1.5;
        }
    }

    // Global state awareness: If we have many open bins, prioritize closing them (lower score for lower residuals).
    // If we have few open bins, we can be more lenient to maintain flexibility.
    let density_factor = (open_bins_count as f64) / (1.0 + mean_residual);
    score += post * density_factor * 0.1;

    // If this is a new bin (bin_residual == bin_capacity), apply a "startup cost" that 
    // decreases as the stream progresses (making it easier to open new bins later).
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress);
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to encourage tight packing.
    // This naturally favors bins where post_residual is close to 0.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" of potential for future items.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
        score += harmonic_penalty * 2.0;
    }

    // 3. Lookahead Logic: If the next item can fit perfectly into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward tight fits for the next item (perfect fit = 0 penalty).
        score -= (100.0 - diff) * 0.5;
    }

    // 4. Threshold Logic: If this is the last fitting bin, avoid opening a new bin at all costs.
    // Penalize the "New Bin" candidate (bin_residual == bin_capacity) if fitting_bins_count > 0.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 500.0;
    }

    // 5. Global state normalization: Gradually prefer tighter packing as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual * 2.0);

    // 6. Penalty for wasting capacity if the item is large (e.g., > 50).
    if item_size > 50 && post_residual > 10 {
        score += (post_residual - 10) as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
