    // 3. Lookahead Logic: If the next item can fit in the current post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.5);
        }
    }

    // 5. Fitting Constraint: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Calibration: Penalize bins that deviate significantly from the mean,
    // encouraging a uniform "tightness" across all open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (residual < 10) because it's too small for any item (min size 10)
    // We heavily penalize small gaps that cannot fit any future items.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // 2. Lookahead optimization: If next_item_size fits in the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open bins pressure: If this is an existing bin, discourage using it if it keeps 
    // the residual very low compared to the mean (trying to keep bins balanced).
    if bin_residual < bin_capacity {
        if (post_residual as f64) < (mean_residual * 0.5) {
            score += 20.0;
        }
    }

    // 4. New bin management: If this is a new bin call (bin_residual == bin_capacity),
    // only choose it if we have no good options.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases as we have more fitting bins available.
        score += (fitting_bins_count as f64) * 80.0;

        // Dynamic threshold: if the stream is nearing the end, be more conservative about new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    } else {
        // 5. Best-Fit logic: Strongly prefer bins that result in a tight fit (low post_residual).
        // This is the baseline: lower post_residual = lower score.
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless the remaining space is extremely fragmented
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 2. Best-Fit logic: prioritize bins that leave little space (low post_residual)
    // but penalize if the resulting space is too small to fit the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: this bin can potentially fit the next item too
            score -= 15.0;
        } else if post_residual > 0 && post_residual < 10 {
            // Bad: creates "dead space" that is too small for any item
            score += 25.0;
        }
    }

    // 3. Balance usage across bins: if this bin's residual is significantly below
    // the mean, it is a "tight" bin; prioritize filling it to keep it tight.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 4. Critical threshold: If this is the last fitting bin, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progression scaling: As we reach the end of the stream, be more conservative
    // with new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}
